/**
 * @embedpdf/plugin-commands/contract — the commands that toolbars, menus,
 * shortcuts and a command palette all show and run.
 *
 * A command's state is read from live state: `resolveCommand` asks the other
 * capabilities when it's called, so every reader follows the kernel's one
 * change stream, with no events. Definitions hold functions, so they live in
 * the settings and the plugin's registry, never in state.
 */
import type {
  CapabilityToken,
  DeepPartial,
  EventHook,
  OperationOptions,
  Permission,
  PluginErrorInfo,
  SettingsApi,
  Unsubscribe,
} from '@embedpdf/core';
import { didYouMean, formatShortcut } from '@embedpdf/core-ui';

export { CommandsToken } from './token';

export type CommandId = string;

/**
 * What a command's derivations and `run` see: capabilities resolved for the command's document
 * (the one named, else the document in scope, else the active one).
 */
export interface CommandContext {
  /** The command's document, or `null` when none is open. */
  readonly documentId: string | null;
  /** What the caller passed: `execute(id, { args })`. */
  readonly args?: unknown;
  /** Fires when the caller cancels `execute()`: pass it on to the calls `run` makes. */
  readonly signal?: AbortSignal;
  /** A capability, for the command's document when the plugin is document-scoped. Throws when it isn't available. */
  get<T>(token: CapabilityToken<T>): T;
  /** Like `get`, but `null` when the capability isn't available (no plugin, no document). */
  tryGet<T>(token: CapabilityToken<T>): T | null;
}

/**
 * Up to two colors that go with a command's icon, such as a tool's current color: data a
 * renderer may use (tint the icon, show a swatch), like `icon` itself.
 */
export interface IconAccent {
  /** The mark: a stroke, the markup or the text color. */
  readonly primary?: string;
  /** The fill, when there is one. */
  readonly secondary?: string;
}

/** One command, as you define it. */
export interface CommandDef {
  /** A unique name, by convention `area:action`: `'zoom:in'`, `'review:approve'`. */
  readonly id: string;
  /** What the user sees. With `labelKey` too, it's what shows when no language has the key. */
  readonly label?: string;
  /**
   * A translation key for the label, read through the i18n plugin. Without the plugin, or a
   * string for the key, the command shows `label`, else the key.
   */
  readonly labelKey?: string;
  /** Your icon's name; your buttons turn it into an icon. */
  readonly icon?: string;
  /** Colors for the icon, read from live state like `active`. */
  readonly iconAccent?: (context: CommandContext) => IconAccent | null;
  /** A key such as `'Mod+K'` (`Mod` is Cmd on a Mac, Ctrl elsewhere), or a list of them. */
  readonly shortcut?: string | readonly string[];
  /**
   * Whether its shortcut also runs while the cursor is in a text field where the shortcuts
   * listen (a search box, a comment), as the viewer's Find does. Default false: a key typed in
   * a field is the field's.
   */
  readonly shortcutInTextFields?: boolean;
  /**
   * The features it belongs to, so turning one off turns it off: `['annotations.highlight']`.
   * Turning off a feature turns off every feature under it, on whole dotted parts: `annotations`
   * covers `annotations.highlight`, not `annotationsExtra`.
   */
  readonly categories?: readonly string[];
  /**
   * The scope permissions it needs, such as `'doc.annotate.modify'`, checked against its
   * document. Without them it's hidden, or shown disabled with its reason under the
   * `notAllowed: 'disable'` setting. With no document open there is nothing to check.
   */
  readonly requires?: readonly Permission[];
  /**
   * Whether the session may run it, from the plugins' `can*` checks
   * (`documents.canPrint()`), for a command whose permission is a plugin's to know. When it
   * says no, the command isn't allowed, as with `requires`. Asked only while a document is
   * open; one that throws allows it.
   */
  readonly allowed?: (context: CommandContext) => boolean;
  /**
   * The translation key of the sentence that says why `allowed` refused it, with `{label}` for
   * its label: `'commands.notAllowed.doc-print'`. Without it, or a string for it,
   * `commands.notAllowed.default`.
   */
  readonly notAllowedKey?: string;

  // ── what the command opens ───────────────────────────────────────────────
  // A command that opens a panel, menu or dialog says so instead of opening
  // it in `run`: it then needs no `run`, it shows as active while the surface
  // is open, and a button can show that it opens a menu.
  /** Opens and closes a menu of yours, by its id. */
  readonly menu?: string;
  /**
   * Opens and closes a panel, closing the others with the same `exclusive` tag. With `focus`,
   * opening it asks for the cursor (the shell's `open(id, { focus: true })`).
   */
  readonly panel?:
    | string
    | { readonly id: string; readonly exclusive?: string; readonly focus?: boolean };
  /** Opens and closes a dialog; one dialog is open at a time. */
  readonly modal?: string;

  // ── read from live state, again whenever anything changes ────────────────
  /** When it can run. Default: always. */
  readonly enabled?: (context: CommandContext) => boolean;
  /** When it shows as pressed, such as the current tool. */
  readonly active?: (context: CommandContext) => boolean;
  /** When it shows at all. Default: always. */
  readonly visible?: (context: CommandContext) => boolean;

  /** What it does; `execute()` resolves once it has. Not needed for a `menu`, `panel` or `modal`. */
  readonly run?: (context: CommandContext) => void | Promise<unknown>;
}

/**
 * A command for each of a set of names, made from one definition, such as `tool:<id>` for every
 * tool a document has. Its commands resolve and run like any other, and `listCommands()` lists
 * one per name. A command defined with the same id wins over the family's.
 */
export interface CommandFamily {
  /** Where the commands' ids start: `'tool:'` makes `tool:highlight`. */
  readonly prefix: string;
  /** The names the command's document has, in order. Return the same array while nothing changed. */
  readonly names: (context: CommandContext) => readonly string[];
  /** The command for one name. A family's commands have no shortcuts. */
  readonly command: (name: string) => Omit<CommandDef, 'id' | 'shortcut'>;
}

/** A command as a button shows it: everything read for its document. */
export interface ResolvedCommand {
  readonly id: string;
  readonly label: string;
  readonly icon?: string;
  readonly iconAccent?: IconAccent;
  readonly shortcuts: readonly string[];
  readonly menu?: string;
  readonly enabled: boolean;
  readonly active: boolean;
  readonly visible: boolean;
  readonly categories: readonly string[];
  /**
   * Why it's disabled, as a sentence for its tooltip: set when the scope doesn't allow it and
   * the `notAllowed` setting is `'disable'`.
   */
  readonly disabledReason?: string;
}

/**
 * Why a command won't run whatever the moment: it's turned off in this viewer
 * (`disabledCategories`, `disabledCommands`), or the scope doesn't allow it (`requires`).
 * A command that only can't run right now (`enabled`, `visible`) has no refusal.
 */
export interface CommandRefusal {
  readonly reason: 'turned-off' | 'not-allowed';
  /** A sentence for the user, translated through the i18n plugin when it's there. */
  readonly message: string;
}

/**
 * Whether two resolved commands show the same, for readers that compare what a command looks
 * like rather than which object holds it (a group of commands, or one command for two documents).
 */
export const resolvedCommandsEqual = (
  left: ResolvedCommand | null,
  right: ResolvedCommand | null,
): boolean => {
  if (left === right) return true;
  if (!left || !right) return false;
  return (
    left.id === right.id &&
    left.label === right.label &&
    left.icon === right.icon &&
    left.iconAccent?.primary === right.iconAccent?.primary &&
    left.iconAccent?.secondary === right.iconAccent?.secondary &&
    left.menu === right.menu &&
    left.enabled === right.enabled &&
    left.active === right.active &&
    left.visible === right.visible &&
    left.disabledReason === right.disabledReason &&
    left.shortcuts.length === right.shortcuts.length &&
    left.shortcuts.every((shortcut, index) => shortcut === right.shortcuts[index])
  );
};

/**
 * What a component or a toolbar draws for a command id no plugin registered: labelled with its
 * id, neither enabled nor visible, the way a turned-off command is.
 */
export const unregisteredCommand = (id: CommandId): ResolvedCommand => ({
  id,
  label: id,
  shortcuts: [],
  enabled: false,
  active: false,
  visible: false,
  categories: [],
});

/** What a component that asks for an id no plugin registered hears, in development. */
export const unknownCommandWarning = (id: CommandId, known: Iterable<CommandId>): string =>
  `no command "${id}"${didYouMean(id, known)}: it shows as neither visible nor enabled`;

/** A command with everything a button needs: what it shows, `run`, and its shortcut for a tooltip. */
export interface BoundCommand extends ResolvedCommand {
  /** Run the command for the document it was read for. */
  readonly run: () => Promise<ExecuteResult>;
  /** Its first shortcut, formatted for the platform (`'⌘K'` on a Mac, `'Ctrl+K'` elsewhere), or `null`. */
  readonly shortcut: string | null;
}

/**
 * A resolved command, bound for a button: `run` executes it through `execute`, and `shortcut` is
 * its first shortcut formatted for the platform. Which platform is the caller's to know
 * (`isMacPlatform()` in `@embedpdf/web`).
 */
export function boundCommandOf(
  command: ResolvedCommand,
  execute: (id: CommandId) => Promise<ExecuteResult>,
  options: { readonly isMac: boolean },
): BoundCommand {
  const [first] = command.shortcuts;
  return {
    ...command,
    run: () => execute(command.id),
    shortcut: first === undefined ? null : formatShortcut(first, { isMac: options.isMac }),
  };
}

/**
 * The commands plugin's settings. `commandsPlugin(config)` registers them over
 * {@link COMMANDS_DEFAULTS}, and `updateSettings()` changes them while the app runs.
 */
export interface CommandsSettings {
  /** The commands your viewer has. A later definition with an id that's taken replaces the earlier one. */
  readonly commands: readonly (CommandDef | CommandFamily)[];
  /**
   * Categories turned off, with every category under them: their commands are hidden and
   * refused wherever they appear.
   */
  readonly disabledCategories: readonly string[];
  /** Commands turned off one by one, by id: hidden and refused wherever they appear. */
  readonly disabledCommands: readonly CommandId[];
  /**
   * What a command the scope doesn't allow does: `'hide'` leaves it out, `'disable'` shows it
   * disabled, with the reason in its `disabledReason`.
   */
  readonly notAllowed: NotAllowedMode;
}

/** How a command shows when the scope doesn't allow it: hidden, or disabled with its reason. */
export type NotAllowedMode = 'hide' | 'disable';

/** What the commands settings are when the app registers none. */
export const COMMANDS_DEFAULTS: CommandsSettings = {
  commands: [],
  disabledCategories: [],
  disabledCommands: [],
  notAllowed: 'hide',
};

/** What `commandsPlugin(config)` takes: any of the settings, merged over the defaults. */
export type CommandsConfig = DeepPartial<CommandsSettings>;

export interface RegisterCommandOptions {
  /** Replace a command with the same id; without it, a taken id throws `conflict`. */
  replace?: boolean;
}

export interface ExecuteOptions extends OperationOptions {
  /** The document to run it for; the document in scope, else the active one, when left out. */
  documentId?: string;
  /** Passed to the command's `run` and derivations as `args`. */
  args?: unknown;
}

/** How `execute()` went: it ran, or it was refused before running, and why. */
export type ExecuteResult =
  | { readonly status: 'executed' }
  | { readonly status: 'rejected'; readonly reason: 'not-found' | 'disabled' | 'hidden' };

// ── events ──
export interface CommandExecutedEvent {
  readonly commandId: CommandId;
  readonly documentId: string | null;
  readonly args: unknown;
}
export interface CommandExecutionFailedEvent {
  readonly commandId: CommandId;
  readonly documentId: string | null;
  readonly error: PluginErrorInfo;
}

/**
 * The commands. A call that leaves out the document is for the document in scope when the
 * capability was resolved for one (`ctx.forDocument`, a `<DocumentScope>`), and for the active
 * document otherwise.
 */
export interface CommandsCapability extends SettingsApi<CommandsSettings> {
  // ── the commands ──
  /**
   * Add a command while the app runs, and get a function that removes it. A taken id throws
   * `conflict` unless `replace`.
   */
  registerCommand(definition: CommandDef, options?: RegisterCommandOptions): Unsubscribe;
  /** `registerCommand` for several definitions; the function removes all of them. */
  registerCommands(
    definitions: readonly CommandDef[],
    options?: RegisterCommandOptions,
  ): Unsubscribe;
  /** Whether a command has this id; with a family, every id that starts with its prefix does. */
  hasCommand(id: CommandId): boolean;
  /** A command as you defined it, or `null`. */
  getCommand(id: CommandId): CommandDef | null;
  /** Every command's id for the active document, in the order they were added. The same array until one changes. */
  listCommandIds(): readonly CommandId[];

  // ── what a button shows ──
  /** A command as a button shows it, or `null` for an unknown id. The same object while nothing about it changed. */
  resolveCommand(id: CommandId, documentId?: string): ResolvedCommand | null;
  /** Every command, resolved, in the order they were added. The same array while nothing changed. */
  listCommands(documentId?: string): readonly ResolvedCommand[];
  /** The visible commands whose label or id contains the query, for a command palette. */
  searchCommands(query: string, documentId?: string): readonly ResolvedCommand[];
  /** Every shortcut with its command, for a keyboard help sheet. The same array until the commands change. */
  listShortcuts(): readonly { readonly commandId: CommandId; readonly shortcut: string }[];

  // ── running them ──
  /**
   * Run a command; resolves once its `run` has, with `{ status: 'executed' }` and
   * `onExecuted`, or `{ status: 'rejected', reason }` for a command that is unknown, hidden or
   * disabled (a command turned off is hidden). A `run` that throws fires `onExecutionFailed` and rejects with its `PluginError`;
   * the signal rejects `operation-cancelled`.
   */
  execute(id: CommandId, options?: ExecuteOptions): Promise<ExecuteResult>;
  /** Whether a command can run now: it exists, and is enabled and visible. */
  canExecute(id: CommandId, documentId?: string): boolean;
  /**
   * Why a command won't run whatever the moment: it's turned off, or not allowed for its
   * document. `null` when it may run (or only can't right now), and for an unknown id.
   */
  getRefusal(id: CommandId, documentId?: string): CommandRefusal | null;

  // ── turning commands off ──
  /** The categories turned off. */
  getDisabledCategories(): readonly string[];
  /** Whether a category is turned off: it, or a category it's under (`annotations` for `annotations.highlight`). */
  isCategoryDisabled(category: string): boolean;
  /** Turn a category off, with every category under it: the `disabledCategories` setting gains it. */
  disableCategory(category: string): void;
  /** Turn a category on again. */
  enableCategory(category: string): void;
  /** Replace the categories that are off. */
  setDisabledCategories(categories: readonly string[]): void;
  /** The commands turned off one by one. */
  getDisabledCommands(): readonly CommandId[];
  /** Whether a command is turned off: by its id, or through one of its categories. */
  isCommandDisabled(id: CommandId): boolean;
  /** Turn one command off: the `disabledCommands` setting gains it. */
  disableCommand(id: CommandId): void;
  /** Turn a command on again; it stays off while one of its categories is. */
  enableCommand(id: CommandId): void;
  /** Replace the commands that are off one by one. */
  setDisabledCommands(ids: readonly CommandId[]): void;

  // ── events ──
  /** A command ran. */
  readonly onExecuted: EventHook<CommandExecutedEvent>;
  /** A command's `run` threw; `execute` rejects with the same error. */
  readonly onExecutionFailed: EventHook<CommandExecutionFailedEvent>;
}

/**
 * @embedpdf/plugin-commands/contract/host — the host lens: the keystroke
 * matcher and the menu a command opens, for the toolbar's "More" menu. The
 * same runtime token as the public contract, typed wider.
 */
import { createHostToken } from '@embedpdf/core';
import type { KeyStroke } from '@embedpdf/core-ui';

import type { CommandId, CommandRefusal, CommandsCapability } from './contract';
import { CommandsToken as PublicCommandsToken } from './token';

export * from './contract';

/** The command a keystroke's shortcut names, and why it won't run when it's refused. */
export interface ShortcutMatch {
  readonly commandId: CommandId;
  /** Set when the command is turned off or not allowed; `null` when it may run (or just can't right now). */
  readonly refusal: CommandRefusal | null;
}

export interface CommandsHostCapability extends CommandsCapability {
  /**
   * The command whose shortcut a keystroke matches, for the active document, or `null`. Of
   * several with the same keys, one that isn't refused wins; a refused one counts only while
   * its `visible` says it would show. With `inTextField` (the key was typed in one), only a
   * command whose `shortcutInTextFields` says so matches.
   */
  matchStroke(
    stroke: KeyStroke,
    options: { isMac: boolean; inTextField?: boolean },
  ): ShortcutMatch | null;
  /** The menu a command opens, for the "More" menu's nested menus; `null` for an unknown id. */
  getMenuTarget(id: CommandId): { menu?: string } | null;
}

export const CommandsToken = createHostToken<CommandsHostCapability>(PublicCommandsToken);

import { definePlugin } from '@embedpdf/core';
import { I18nToken } from '@embedpdf/plugin-i18n/contract';
import { ShellToken } from '@embedpdf/plugin-shell/contract';

import { COMMANDS_DEFAULTS, type CommandsConfig } from './contract';
import { createCommandsController } from './controller';
import { CommandsToken } from './host-contract';

/**
 * The commands: one set for the whole workspace, each resolved and run for a
 * document (the one named, else the document in scope, else the active one).
 * Definitions are settings and app content, never state, since they hold
 * functions. `config` is the settings the app registers, over
 * {@link COMMANDS_DEFAULTS}.
 */
export const commandsPlugin = (config?: CommandsConfig) =>
  definePlugin({
    id: 'commands',
    scope: 'workspace',
    token: CommandsToken,
    // Labels come from i18n, and commands that open a panel, menu or dialog
    // go through shell; without them a label is the command's own, and those
    // commands open nothing.
    optional: [I18nToken, ShellToken],
    // Command definitions come from the app and may use any capability.
    resolvesAnyCapability: true,
    settings: { defaults: COMMANDS_DEFAULTS, registered: config },
    create: createCommandsController,
    // Inside a document's scope, a call that leaves out the document is for that one.
    inScope: (commands, documentId) => ({
      ...commands,
      resolveCommand: (id, target = documentId) => commands.resolveCommand(id, target),
      listCommands: (target = documentId) => commands.listCommands(target),
      searchCommands: (query, target = documentId) => commands.searchCommands(query, target),
      execute: (id, options) =>
        commands.execute(id, { ...options, documentId: options?.documentId ?? documentId }),
      canExecute: (id, target = documentId) => commands.canExecute(id, target),
      getRefusal: (id, target = documentId) => commands.getRefusal(id, target),
    }),
  });

/**
 * The commands controller: the commands (from the settings, added while the
 * app runs, and from families), resolution for a document (derivations over
 * live state, safe to throw), the one way to run a command, turning commands
 * off (by category and one by one), what the session may run (the scope's
 * `requires`, the plugins' checks in `allowed`), and the host-only keystroke
 * matcher.
 *
 * Definitions hold functions, so the commands added while the app runs are a
 * map outside state; every change to it calls `ctx.notify()` so readers read
 * again.
 */
import {
  DocumentsToken,
  isPluginError,
  memo,
  memoByKey,
  PluginError,
  toPluginError,
  toPluginErrorInfo,
  type CapabilityToken,
  type PluginContext,
  type Unsubscribe,
} from '@embedpdf/core';
import { matchShortcut, type KeyStroke } from '@embedpdf/core-ui';
import { ShellToken } from '@embedpdf/plugin-shell/contract';

import type {
  CommandContext,
  CommandDef,
  CommandExecutedEvent,
  CommandExecutionFailedEvent,
  CommandFamily,
  CommandsSettings,
  ExecuteOptions,
  ExecuteResult,
  IconAccent,
  RegisterCommandOptions,
  ResolvedCommand,
} from './contract';
import type { CommandsHostCapability, ShortcutMatch } from './host-contract';
import {
  configuredCommands,
  registeredCommand,
  type ConfiguredCommands,
  type RegisteredCommand,
} from './registry';
import { createAvailability, labelOf, notAllowedMessage } from './services/availability';
import { createTurningOff } from './write/turning-off';

const panelTarget = (
  definition: CommandDef,
): { id: string; exclusive?: string; focus?: boolean } | null =>
  definition.panel === undefined
    ? null
    : typeof definition.panel === 'string'
      ? { id: definition.panel }
      : definition.panel;

/**
 * One command's live derivations for a document, as values a memo can
 * compare: the entry, label, accent colors, the enabled/active/visible flags,
 * and why it's disabled when the scope doesn't allow it.
 */
type Derivations = readonly [
  entry: RegisteredCommand | null,
  label: string,
  accentPrimary: string | undefined,
  accentSecondary: string | undefined,
  enabled: boolean,
  active: boolean,
  visible: boolean,
  disabledReason: string | undefined,
];

const NOT_REGISTERED: Derivations = [
  null,
  '',
  undefined,
  undefined,
  false,
  false,
  false,
  undefined,
];
const NO_NAMES: readonly string[] = [];

const accentOf = (primary?: string, secondary?: string): IconAccent | undefined =>
  primary === undefined && secondary === undefined
    ? undefined
    : {
        ...(primary !== undefined ? { primary } : {}),
        ...(secondary !== undefined ? { secondary } : {}),
      };

/** The memo key of a resolution: the command id and the document named, if any. */
const resolutionKey = (id: string, documentId: string | undefined): string =>
  JSON.stringify([id, documentId ?? null]);

export function createCommandsController(ctx: PluginContext<void, CommandsSettings>) {
  const settings = ctx.settings();

  /** Commands added while the app runs, in the order they were added. */
  const registered = new Map<string, RegisteredCommand>();
  /** Bumped on every change to `registered`: the input of the reads built from it. */
  let registeredVersion = 0;
  const registeredChanged = (): void => {
    registeredVersion += 1;
    ctx.notify();
  };

  /** The commands the settings define, rebuilt when the setting changes. */
  const configured = memo(
    () => [settings.get().commands],
    (items): ConfiguredCommands => configuredCommands(items),
  );

  const executed = ctx.events.source<CommandExecutedEvent>();
  const executionFailed = ctx.events.source<CommandExecutionFailedEvent>();

  /** Capabilities for the command's document: the one named, else the active one. */
  const commandContext = (
    documentId?: string,
    call: { args?: unknown; signal?: AbortSignal } = {},
  ): CommandContext => {
    const target = documentId ?? ctx.get(DocumentsToken).getActiveId();
    const get = <T>(token: CapabilityToken<T>): T =>
      target ? ctx.forDocument(token, target) : ctx.get(token);
    return {
      documentId: target,
      ...(call.args === undefined ? {} : { args: call.args }),
      ...(call.signal ? { signal: call.signal } : {}),
      get,
      tryGet: <T>(token: CapabilityToken<T>): T | null => {
        try {
          return get(token);
        } catch {
          return null;
        }
      },
    };
  };

  /** A family's command for one name, made once so it keeps its identity. */
  const familyCommands = new WeakMap<CommandFamily, Map<string, RegisteredCommand>>();
  const familyCommand = (family: CommandFamily, name: string): RegisteredCommand => {
    let byName = familyCommands.get(family);
    if (!byName) {
      byName = new Map();
      familyCommands.set(family, byName);
    }
    let entry = byName.get(name);
    if (!entry) {
      entry = registeredCommand({ ...family.command(name), id: `${family.prefix}${name}` });
      byName.set(name, entry);
    }
    return entry;
  };

  /** The command with this id: one added while the app runs, else the settings', else a family's. */
  const entryOf = (id: string): RegisteredCommand | null => {
    const { commands, families } = configured();
    const entry = registered.get(id) ?? commands.get(id);
    if (entry) return entry;
    const family = families.find(
      (candidate) => id.startsWith(candidate.prefix) && id.length > candidate.prefix.length,
    );
    return family ? familyCommand(family, id.slice(family.prefix.length)) : null;
  };

  /** Every command with its own definition (not a family's), each id once. */
  const definedCommands = memo(
    () => [registeredVersion, configured()],
    (_version, { commands }) => {
      const entries = new Map(commands);
      for (const [id, entry] of registered) entries.set(id, entry);
      return [...entries.values()];
    },
  );

  // Derivations run against live state; one that throws (it needs a document
  // and none is open, say) falls back to a safe default, so the button renders
  // disabled instead of breaking.
  const derive = (
    derivation: ((context: CommandContext) => boolean) | undefined,
    context: CommandContext,
    fallback: boolean,
  ): boolean => {
    if (!derivation) return fallback;
    try {
      return derivation(context);
    } catch {
      return fallback;
    }
  };
  const deriveAccent = (
    derivation: ((context: CommandContext) => IconAccent | null) | undefined,
    context: CommandContext,
  ): IconAccent | undefined => {
    if (!derivation) return undefined;
    try {
      return derivation(context) ?? undefined;
    } catch {
      return undefined;
    }
  };
  const namesOf = (family: CommandFamily, context: CommandContext): readonly string[] => {
    try {
      return family.names(context);
    } catch {
      return NO_NAMES;
    }
  };

  const { isTurnedOff, notAllowedKeyOf, refusalOf } = createAvailability(ctx, settings);

  const derivationsOf = (entry: RegisteredCommand, documentId?: string): Derivations => {
    const { definition } = entry;
    const context = commandContext(documentId);
    const label = labelOf(definition, context);
    // Turned off hides it; not allowed hides it, or disables it with the reason.
    const turnedOff = isTurnedOff(definition);
    const notAllowed = turnedOff ? null : notAllowedKeyOf(definition, context);
    const shownWhenNotAllowed = settings.get().notAllowed === 'disable';
    const ruledOut = turnedOff || notAllowed !== null;
    // A command that opens something is active while it's open, unless it says otherwise.
    let active: boolean;
    if (definition.active) {
      active = derive(definition.active, context, false);
    } else {
      const shell = context.tryGet(ShellToken);
      const panel = panelTarget(definition);
      active = shell
        ? definition.menu
          ? shell.isMenuOpen(definition.menu)
          : panel
            ? shell.isOpen(panel.id)
            : definition.modal
              ? shell.isOpen(definition.modal)
              : false
        : false;
    }
    const accent = deriveAccent(definition.iconAccent, context);
    return [
      entry,
      label,
      accent?.primary,
      accent?.secondary,
      !ruledOut && derive(definition.enabled, context, true),
      active,
      !turnedOff &&
        (notAllowed === null || shownWhenNotAllowed) &&
        derive(definition.visible, context, true),
      notAllowed !== null && shownWhenNotAllowed
        ? notAllowedMessage(notAllowed, label, context)
        : undefined,
    ];
  };

  /** A resolved command, the same object until one of its derivations or its entry changes. */
  const resolvedByKey = memoByKey(
    (key: string): Derivations => {
      const [id, documentId] = JSON.parse(key) as [string, string | null];
      const entry = entryOf(id);
      return entry ? derivationsOf(entry, documentId ?? undefined) : NOT_REGISTERED;
    },
    (
      _key,
      entry,
      label,
      accentPrimary,
      accentSecondary,
      enabled,
      active,
      visible,
      disabledReason,
    ): ResolvedCommand | null =>
      entry && {
        id: entry.definition.id,
        label,
        icon: entry.definition.icon,
        iconAccent: accentOf(accentPrimary, accentSecondary),
        shortcuts: entry.shortcuts,
        menu: entry.definition.menu,
        enabled,
        active,
        visible,
        categories: entry.definition.categories ?? [],
        ...(disabledReason === undefined ? {} : { disabledReason }),
      },
  );
  const resolveCommand = (id: string, documentId?: string): ResolvedCommand | null =>
    entryOf(id) ? resolvedByKey(resolutionKey(id, documentId)) : null;

  /**
   * Every command's id for a document (`''` is the active one): the defined ones in the order
   * they were added, then each family's names that no defined command took.
   */
  const idsByDocument = memoByKey(
    (documentKey: string): readonly unknown[] => {
      const config = configured();
      const context = commandContext(documentKey || undefined);
      return [
        definedCommands(),
        config,
        ...config.families.map((family) => namesOf(family, context)),
      ];
    },
    (_documentKey, ...inputs): readonly string[] => {
      const [defined, { families }, ...names] = inputs as [
        readonly RegisteredCommand[],
        ConfiguredCommands,
        ...(readonly string[])[],
      ];
      const ids = defined.map((entry) => entry.definition.id);
      const taken = new Set(ids);
      families.forEach((family, index) => {
        for (const name of names[index] ?? NO_NAMES) {
          const id = `${family.prefix}${name}`;
          if (taken.has(id)) continue;
          taken.add(id);
          ids.push(id);
        }
      });
      return ids;
    },
  );
  const commandsByDocument = memoByKey(
    (documentKey: string) =>
      idsByDocument(documentKey).map((id) => resolveCommand(id, documentKey || undefined)),
    (_documentKey, ...resolved) =>
      resolved.filter((command): command is ResolvedCommand => command !== null),
  );
  const listCommands = (documentId?: string): readonly ResolvedCommand[] =>
    commandsByDocument(documentId ?? '');

  const listShortcuts = memo(
    () => [definedCommands()],
    (entries) =>
      entries.flatMap((entry) =>
        entry.shortcuts.map((shortcut) => ({ commandId: entry.definition.id, shortcut })),
      ),
  );

  /** What running a command does: its `run`, or opening what it opens. */
  const runCommand = async (definition: CommandDef, context: CommandContext): Promise<void> => {
    if (definition.run) {
      await definition.run(context);
      return;
    }
    const shell = context.tryGet(ShellToken);
    const panel = panelTarget(definition);
    if (!shell) return;
    if (definition.menu) shell.toggleMenu(definition.menu);
    else if (panel) shell.toggle(panel.id, { exclusive: panel.exclusive, focus: panel.focus });
    else if (definition.modal) shell.toggle(definition.modal, { exclusive: 'modal' });
  };

  const execute = async (id: string, options: ExecuteOptions = {}): Promise<ExecuteResult> => {
    const { signal, documentId, args } = options;
    if (signal?.aborted) {
      throw new PluginError('operation-cancelled', 'commands', 'operation cancelled');
    }
    const entry = entryOf(id);
    if (!entry) return { status: 'rejected', reason: 'not-found' };
    const resolved = resolveCommand(id, documentId);
    if (!resolved?.visible) return { status: 'rejected', reason: 'hidden' };
    if (!resolved.enabled) return { status: 'rejected', reason: 'disabled' };
    const context = commandContext(documentId, { args, signal });
    try {
      await ctx.cancellable(signal, runCommand(entry.definition, context));
    } catch (error) {
      // The caller cancelling isn't the command failing.
      if (signal?.aborted && isPluginError(error, 'operation-cancelled')) throw error;
      const failure = toPluginError('commands', error);
      executionFailed.emit({
        commandId: id,
        documentId: context.documentId,
        error: toPluginErrorInfo(failure),
      });
      throw failure;
    }
    executed.emit({ commandId: id, documentId: context.documentId, args });
    return { status: 'executed' };
  };

  const registerOne = (definition: CommandDef, options?: RegisterCommandOptions): Unsubscribe => {
    const taken = registered.has(definition.id) || configured().commands.has(definition.id);
    if (taken && !options?.replace) {
      throw new PluginError('conflict', 'commands', `duplicate command '${definition.id}'`);
    }
    const entry = registeredCommand(definition);
    registered.set(definition.id, entry);
    registeredChanged();
    return () => {
      // Own this registration only: a later replacement is not ours to remove.
      if (registered.get(definition.id) !== entry) return;
      registered.delete(definition.id);
      registeredChanged();
    };
  };

  const turningOff = createTurningOff(
    settings,
    (id) => entryOf(id)?.definition ?? null,
    isTurnedOff,
  );

  const api: CommandsHostCapability = {
    ...settings.api,
    registerCommand: registerOne,
    registerCommands: (definitions, options) => {
      const removers = definitions.map((definition) => registerOne(definition, options));
      return () => removers.forEach((remove) => remove());
    },
    hasCommand: (id) => entryOf(id) !== null,
    getCommand: (id) => entryOf(id)?.definition ?? null,
    listCommandIds: () => idsByDocument(''),
    resolveCommand,
    listCommands,
    searchCommands: (query, documentId) => {
      const needle = query.trim().toLowerCase();
      return listCommands(documentId).filter(
        (command) =>
          command.visible &&
          (needle === '' ||
            command.label.toLowerCase().includes(needle) ||
            command.id.includes(needle)),
      );
    },
    listShortcuts,
    execute,
    canExecute: (id, documentId) => {
      const resolved = resolveCommand(id, documentId);
      return !!resolved && resolved.enabled && resolved.visible;
    },
    getRefusal: (id, documentId) => {
      const entry = entryOf(id);
      return entry ? refusalOf(entry.definition, commandContext(documentId)) : null;
    },
    ...turningOff,
    onExecuted: executed.on,
    onExecutionFailed: executionFailed.on,
    // ── host lens ──
    matchStroke: (stroke: KeyStroke, options) => {
      let refused: ShortcutMatch | null = null;
      for (const entry of definedCommands()) {
        if (options.inTextField && !entry.definition.shortcutInTextFields) continue;
        if (!entry.parsed.some((shortcut) => matchShortcut(shortcut, stroke, options))) continue;
        const context = commandContext();
        const refusal = refusalOf(entry.definition, context);
        if (!refusal) return { commandId: entry.definition.id, refusal: null };
        // A refused command takes its keys only where it would show: Delete with nothing
        // selected stays the page's, even where deleting is turned off.
        if (!derive(entry.definition.visible, context, true)) continue;
        refused ??= { commandId: entry.definition.id, refusal };
      }
      return refused;
    },
    getMenuTarget: (id) => {
      const entry = entryOf(id);
      return entry ? { menu: entry.definition.menu } : null;
    },
  };

  return { api };
}

/** A command definition with its shortcuts parsed once, and how the registry tells a family apart. */
import { parseShortcut, type ParsedShortcut } from '@embedpdf/core-ui';

import type { CommandDef, CommandFamily } from './contract';

export interface RegisteredCommand {
  readonly definition: CommandDef;
  readonly shortcuts: readonly string[];
  readonly parsed: readonly ParsedShortcut[];
}

export const registeredCommand = (definition: CommandDef): RegisteredCommand => {
  const shortcuts =
    definition.shortcut === undefined ? [] : ([] as string[]).concat(definition.shortcut);
  return { definition, shortcuts, parsed: shortcuts.map(parseShortcut) };
};

export const isCommandFamily = (item: CommandDef | CommandFamily): item is CommandFamily =>
  'prefix' in item;

/** The commands the settings define, by id (a later id replaces an earlier one), and their families. */
export interface ConfiguredCommands {
  readonly commands: ReadonlyMap<string, RegisteredCommand>;
  readonly families: readonly CommandFamily[];
}

export function configuredCommands(
  items: readonly (CommandDef | CommandFamily)[],
): ConfiguredCommands {
  const commands = new Map<string, RegisteredCommand>();
  const families: CommandFamily[] = [];
  for (const item of items) {
    if (isCommandFamily(item)) families.push(item);
    else commands.set(item.id, registeredCommand(item));
  }
  return { commands, families };
}

/**
 * Whether a command is there at all, apart from what it says about the
 * moment (`enabled`, `visible`): turned off in this viewer (its id, or one of
 * its categories), or not allowed for its document (the scope's `requires`, or
 * the plugins' checks in `allowed`), and the sentence that says why, translated
 * when the i18n plugin is there.
 */
import type { DocumentHandle, Permission, PluginContext, Settings } from '@embedpdf/core';
import { I18nToken } from '@embedpdf/plugin-i18n/contract';

import type { CommandContext, CommandDef, CommandRefusal, CommandsSettings } from '../contract';

/**
 * Whether a category is off: it, or a category it's under, is in the list. Parts are whole
 * dotted segments, so `annotations` covers `annotations.highlight` and not `annotationsExtra`.
 */
export const isCategoryOff = (category: string, disabled: readonly string[]): boolean =>
  disabled.some((off) => category === off || category.startsWith(`${off}.`));

/**
 * The label: a language's string under the command's id, else under its `labelKey` (the current
 * language, then the fallback one), else `label`, else the id. So a string for
 * `'document:download'` relabels that one command, whichever key its label is under.
 */
export const labelOf = (definition: CommandDef, context: CommandContext): string => {
  const i18n = context.tryGet(I18nToken);
  if (!i18n) return definition.label ?? definition.labelKey ?? definition.id;
  const fallbackKey = definition.labelKey ? { fallbackKey: definition.labelKey } : {};
  // A command with a key and no label of its own warns once when no language has the key.
  return definition.label === undefined && definition.labelKey
    ? i18n.t(definition.id, fallbackKey)
    : i18n.t(definition.id, { ...fallbackKey, fallback: definition.label ?? definition.id });
};

/**
 * Whether a document's session holds a permission: what `ctx.allows` answers for a
 * document-scoped plugin, asked here of the command's document, since the commands are one
 * set for the whole workspace.
 */
const sessionHolds = (security: DocumentHandle['security'], permission: Permission): boolean =>
  permission === 'annotations:create'
    ? security.allowsAnnotation('create')
    : security.allows(permission);

/** Where a language keeps the sentence for a permission: `commands.notAllowed.doc-text-copy`. */
const permissionKeyOf = (permission: Permission): string =>
  `commands.notAllowed.${permission.replace(/[.:]/g, '-')}`;

/** The general sentence's key: `{label} isn't allowed`. */
const DEFAULT_NOT_ALLOWED_KEY = 'commands.notAllowed.default';

/** The sentence for a command the session may not run, under `key`, else the general one. */
export const notAllowedMessage = (key: string, label: string, context: CommandContext): string => {
  const fallback = `${label} isn't allowed`;
  const i18n = context.tryGet(I18nToken);
  if (!i18n) return fallback;
  const params = { label };
  return i18n.t(key, {
    params,
    fallback: i18n.t(DEFAULT_NOT_ALLOWED_KEY, { params, fallback }),
  });
};

/** The sentence for a command that's turned off. */
const turnedOffMessage = (label: string, context: CommandContext): string => {
  const i18n = context.tryGet(I18nToken);
  return i18n
    ? i18n.t('commands.turnedOff', { params: { label }, fallback: "{label} isn't available" })
    : `${label} isn't available`;
};

export function createAvailability(
  ctx: PluginContext<void, CommandsSettings>,
  settings: Settings<CommandsSettings>,
) {
  /** Whether a command is turned off: by its id, or through one of its categories. */
  const isTurnedOff = (definition: CommandDef): boolean => {
    const { disabledCategories, disabledCommands } = settings.get();
    return (
      disabledCommands.includes(definition.id) ||
      (definition.categories ?? []).some((category) => isCategoryOff(category, disabledCategories))
    );
  };

  /** Whether a command's `allowed` check says yes; one that throws allows it. */
  const passesCheck = (definition: CommandDef, context: CommandContext): boolean => {
    if (!definition.allowed) return true;
    try {
      return definition.allowed(context);
    } catch {
      return true;
    }
  };

  /**
   * Why its document's session may not run a command, as the key of the sentence that says
   * so, or `null` when it may: the first permission `requires` names that the session doesn't
   * hold (`commands.notAllowed.doc-print`), else its `allowed` check saying no (its
   * `notAllowedKey`). With no document open there is no session to ask, and nothing is refused.
   */
  const notAllowedKeyOf = (definition: CommandDef, context: CommandContext): string | null => {
    if (!definition.requires?.length && !definition.allowed) return null;
    const handle = context.documentId === null ? null : ctx.documentHandle(context.documentId);
    if (!handle) return null;
    const missing = definition.requires?.find(
      (permission) => !sessionHolds(handle.security, permission),
    );
    if (missing !== undefined) return permissionKeyOf(missing);
    return passesCheck(definition, context)
      ? null
      : (definition.notAllowedKey ?? DEFAULT_NOT_ALLOWED_KEY);
  };

  /** Why a command won't run whatever the moment, or `null` when it may run. */
  const refusalOf = (definition: CommandDef, context: CommandContext): CommandRefusal | null => {
    if (isTurnedOff(definition)) {
      return {
        reason: 'turned-off',
        message: turnedOffMessage(labelOf(definition, context), context),
      };
    }
    const notAllowed = notAllowedKeyOf(definition, context);
    return notAllowed === null
      ? null
      : {
          reason: 'not-allowed',
          message: notAllowedMessage(notAllowed, labelOf(definition, context), context),
        };
  };

  return { isTurnedOff, notAllowedKeyOf, refusalOf };
}

/**
 * Turning commands off and on: by category, with every category under it, and
 * one by one. Both lists are settings, so they change live and
 * `resetSettings()` restores what the app registered.
 */
import type { Settings } from '@embedpdf/core';

import type { CommandDef, CommandsCapability, CommandsSettings } from '../contract';
import { isCategoryOff } from '../services/availability';

type OffList = 'disabledCategories' | 'disabledCommands';

export function createTurningOff(
  settings: Settings<CommandsSettings>,
  definitionOf: (id: string) => CommandDef | null,
  isTurnedOff: (definition: CommandDef) => boolean,
) {
  const listOf = (list: OffList): readonly string[] => settings.get()[list];
  const replace = (list: OffList, names: readonly string[]): void =>
    settings.api.updateSettings(
      list === 'disabledCategories'
        ? { disabledCategories: [...names] }
        : { disabledCommands: [...names] },
    );
  // Adding a name that's there, or removing one that isn't, changes nothing and fires nothing.
  const add = (list: OffList, name: string): void => {
    const current = listOf(list);
    if (!current.includes(name)) replace(list, [...current, name]);
  };
  const remove = (list: OffList, name: string): void => {
    const current = listOf(list);
    if (current.includes(name))
      replace(
        list,
        current.filter((other) => other !== name),
      );
  };

  return {
    getDisabledCategories: () => listOf('disabledCategories'),
    isCategoryDisabled: (category) => isCategoryOff(category, listOf('disabledCategories')),
    disableCategory: (category) => add('disabledCategories', category),
    enableCategory: (category) => remove('disabledCategories', category),
    setDisabledCategories: (categories) => replace('disabledCategories', categories),
    getDisabledCommands: () => listOf('disabledCommands'),
    isCommandDisabled: (id) => {
      const definition = definitionOf(id);
      return definition ? isTurnedOff(definition) : listOf('disabledCommands').includes(id);
    },
    disableCommand: (id) => add('disabledCommands', id),
    enableCommand: (id) => remove('disabledCommands', id),
    setDisabledCommands: (ids) => replace('disabledCommands', ids),
  } satisfies Partial<CommandsCapability>;
}

