const EMPTY_PAGES: readonly PageLayout[] = Object.freeze([]);

/** The new page registry a document mutation carries, or null for events that
 *  don't change page structure (annotations, metadata). The snapshot is the
 *  same shape `pages.list()` returns, so callers swap it in directly. */
function layoutFromEvent(event: DocumentEvent) {
  switch (event.type) {
    case 'pages.reordered':
    case 'pages.rotated':
    case 'pages.deleted':
    case 'pages.inserted':
    case 'pages.restored':
      return event.layout;
    default:
      return null;
  }
}

/** Kernel lifecycle. Monotonic: created → starting → started, then destroying →
 *  destroyed; `failed` is a terminal branch off starting. */
export type KernelStatus =
  | 'created'
  | 'starting'
  | 'started'
  | 'failed'
  | 'destroying'
  | 'destroyed';

/**
 * The viewer: the engine, the plugins and the open documents. Its own settings
 * (`getSettings()`, `updateSettings()`, …) are what every document gets unless it says
 * otherwise, and what every plugin's colors fall back to (`viewer-settings.ts`).
 */
export interface Kernel extends SettingsApi<ViewerSettings> {
  readonly engine: Engine;
  readonly documents: DocumentsCapability;
  /**
   * Resolve a capability. For document-scoped tokens, `documentId` defaults to the active doc.
   * For a workspace token, a `documentId` gives the capability as seen from that document's
   * scope (`PluginDef.inScope`; the documents capability too): the same object on every call
   * while the document is open.
   */
  capability<T>(token: CapabilityToken<T>, documentId?: string): T;
  /**
   * Total sibling of `capability()`: `null` instead of throwing — no
   * provider, no document, or a document that isn't `ready` yet. This is the
   * method adapters subscribe to (`useKernelValue`-style): resolution is a
   * value derived from kernel state, not a pure function of its arguments —
   * a pending document's promotion changes the result while the id stays the
   * same, so caching a `capability()` call by id goes stale. The returned
   * instance is reference-stable per (plugin, document), so equality-cached
   * reads don't churn.
   */
  tryCapability<T>(token: CapabilityToken<T>, documentId?: string): T | null;
  /** A token's scope — adapters use this to decide whether to bind a document. */
  scopeOf(token: CapabilityToken<unknown>): PluginScope;
  /**
   * A plugin's settings calls, with or without a document open: settings belong to the plugin
   * as the app registered it, not to a document. For adapters (a settings hook renders before
   * the first document opens) and for an app that changes them before opening one. Throws
   * when no installed plugin provides `token`, or its plugin declares no settings.
   */
  settingsOf<C>(token: CapabilityToken<C>): SettingsApi<SettingsOf<C>>;
  subscribe(listener: () => void): Unsubscribe;
  getState(): GlobalState;
  status(): KernelStatus;
  /** Idempotent: a second call joins the first. Throws after destroy(). */
  start(): Promise<void>;
  /**
   * Idempotent: every call returns the same promise. Joins an in-flight
   * start(), closes every document (their engine handles included), then
   * unwinds workspace resources. Never throws.
   */
  destroy(): Promise<void>;
}

const isDocumentScoped = (plugin: AnyPlugin) => plugin.scope === 'document';
const initialStateOf = (plugin: AnyPlugin): unknown => plugin.state?.();
/**
 * A document's public fields, one object per registry entry: the entries are replaced, never
 * changed, so the same entry gives the same object, and readers re-render only for their own.
 */
const infoByEntry = new WeakMap<DocumentMeta | PendingMeta, DocumentInfo>();
function documentInfoOf(entry: DocumentMeta | PendingMeta): DocumentInfo {
  let info = infoByEntry.get(entry);
  if (!info) {
    info = 'pages' in entry ? readyInfo(entry) : pendingInfo(entry);
    infoByEntry.set(entry, info);
  }
  return info;
}
const readyInfo = (meta: DocumentMeta): DocumentInfo =>
  Object.freeze({
    id: meta.id,
    name: meta.name,
    status: 'ready',
    pageCount: meta.pageCount,
    hasUnsavedChanges: meta.hasUnsavedChanges,
  });
const pendingInfo = (meta: PendingMeta): DocumentInfo =>
  Object.freeze({
    id: meta.id,
    name: meta.name,
    status: meta.status,
    pageCount: 0,
    hasUnsavedChanges: false,
    ...(meta.status === 'locked' ? { passwordProvided: meta.passwordProvided ?? false } : {}),
    ...(meta.status === 'error' && meta.error !== undefined
      ? { error: toPluginErrorInfo(toPluginError('documents', meta.error)) }
      : {}),
  });

/** Whether an event is a change to the document, one a download would carry. */
const changesDocument = (event: DocumentEvent): boolean =>
  event.type !== 'stream.desynced' &&
  event.type !== 'document.versioned' &&
  event.type !== 'signatures.prepared' &&
  event.type !== 'signatures.cancelled';

/** The part of `fetch` a `{ kind: 'url' }` source needs. */
type FetchFile = (
  url: string,
  init: { readonly signal: AbortSignal },
) => Promise<{
  readonly ok: boolean;
  readonly status: number;
  arrayBuffer(): Promise<ArrayBuffer>;
}>;

/** Download a URL source's file; its tab shows the failure when the server says no. */
async function fetchUrlSource(source: UrlSource, signal: AbortSignal): Promise<OpenInput> {
  const fetchFile = (globalThis as { fetch?: FetchFile }).fetch;
  if (!fetchFile) {
    throw new PluginError('unsupported', 'documents', `can't download ${source.url}: no fetch()`);
  }
  const response = await fetchFile(source.url, { signal });
  if (!response.ok) {
    throw new PluginError(
      response.status === 404 ? 'not-found' : 'operation-failed',
      'documents',
      `couldn't download ${source.url} (HTTP ${response.status})`,
    );
  }
  return { kind: 'bytes', bytes: new Uint8Array(await response.arrayBuffer()) };
}

const isUrlSource = (source: OpenInput | UrlSource): source is UrlSource => source.kind === 'url';

const noLayer = () =>
  new PluginError('unsupported', 'documents', 'only the local engine gives a layer to download');

/** How a print comes out at each tier, one object each, so readers can compare them with `Object.is`. */
const PRINT_STANDARD: PrintQuality = Object.freeze({ kind: 'images', dpi: 150 });
const PRINT_HIGH: Extract<PrintQuality, { kind: 'images' }> = Object.freeze({
  kind: 'images',
  dpi: 300,
});
const PRINT_PDF: PrintQuality = Object.freeze({ kind: 'pdf' });

/** One print being staged: the document, its pages, what prints beside them, the job's name. */
interface PrintJob {
  readonly handle: DocumentHandle;
  readonly pages: readonly PageInfo[];
  readonly layers: { readonly includeAnnotations: boolean; readonly includeFormFields: boolean };
  readonly name: string;
  readonly options: PrintOptions;
}

/**
 * The documents capability as seen from inside one document's scope: every call whose document
 * is optional uses that document instead of the active one. The rest is the registry itself.
 */
const documentsInScope = (
  documents: DocumentsCapability,
  documentId: string,
): DocumentsCapability => ({
  ...documents,
  get: (id = documentId) => documents.get(id),
  download: (id = documentId, options) => documents.download(id, options),
  downloadLayer: (id = documentId, options) => documents.downloadLayer(id, options),
  canDownload: (id = documentId) => documents.canDownload(id),
  preparePrint: (id = documentId, options) => documents.preparePrint(id, options),
  print: (id = documentId, options) => documents.print(id, options),
  getPrintQuality: (id = documentId) => documents.getPrintQuality(id),
  canPrint: (id = documentId) => documents.canPrint(id),
  listPages: (id = documentId) => documents.listPages(id),
  getPage: (page, id = documentId) => documents.getPage(page, id),
  getPageIndex: (ref, id = documentId) => documents.getPageIndex(ref, id),
  getRevision: (id = documentId) => documents.getRevision(id),
});

/** The stable id an input implies, if it carries one ('bytes'/'layerBytes'/'id'). */
const idOfInput = (input: OpenInput | UrlSource): string | null =>
  'id' in input && typeof input.id === 'string' ? input.id : null;

/**
 * Everything one open document owns, in one place: the engine handle, the
 * resource scope (event subs, slices, plugin cleanups, the handle's own
 * close), the capability instances, and the in-flight lifecycle operation.
 * The session is the document's lifecycle; the store's `documents`/`pending`
 * entries are its UI projection.
 *
 *   opening — slot reserved; source resolving / engine opening
 *   locked  — parked on a password; the scope already owns handle.close
 *   bringup — post-security: slices, construction, connection; not yet published
 *   ready   — committed; the only phase adapters resolve capabilities in
 *   error   — open failed after the slot was reserved; resources disposed
 *   closing — close() won; unpublished, joining the operation, disposing
 */
interface DocumentSession extends SessionRef {
  name?: string;
  /** What `open()` was called with, so a failed tab can `retry()`. */
  source: OpenSource | null;
  openOptions: OpenDocumentOptions | undefined;
  phase: 'opening' | 'locked' | 'bringup' | 'ready' | 'error' | 'closing';
  /** In-flight open/unlock — close() cancels, then joins this before disposing,
   *  so "close resolved" means "no producer is still acquiring resources". */
  operation: Promise<unknown> | null;
  /** The current engine call, retained so close() can abort real worker-side
   *  work instead of waiting for it to land at a checkpoint. */
  engineOp: { abort(reason?: unknown): void } | null;
  cancel: AbortController;
  capabilities: Map<AnyPlugin, unknown>;
  /**
   * The plugins whose `create()` is running. A read that reaches one of them meanwhile finds
   * no capability yet, instead of building it a second time. (Listeners can't cause one: the
   * store holds its notifications while a document's plugins are built.)
   */
  building: Set<AnyPlugin>;
  /** Workspace capabilities as seen from this document's scope (`PluginDef.inScope`), by token. */
  views: Map<CapabilityToken<unknown>, unknown>;
  /** `connect` halves of `create()`, run once every instance of the document is built. */
  connectors: Map<AnyPlugin, () => void>;
  /** How many changes the document has had since it opened: a download that read them all clears `hasUnsavedChanges`. */
  changeCount: number;
  /**
   * How many changes the document has had since it opened, on any engine and from any session:
   * a prepared print that saw fewer is prepared again before it prints.
   */
  changesSeen: number;
  close(): Promise<void>;
}

let instanceCounter = 0;

/** Engine rejections carry AbortError when close() aborts the live call;
 *  match structurally so test fakes with plain promises still work. */
const isAbortLike = (error: unknown): boolean =>
  error instanceof Error && error.name === 'AbortError';

/**
 * Assemble a kernel from an engine + plugins.
 *
 *   planPlugins        — validate dependencies, order them
 *   resolveCapability  — workspace singletons (or their view from a document's scope),
 *                        or per-document instances built lazily
 *   settings           — one store per plugin registration, built up front, shared
 *                        by its instances and readable with no document
 *   document lifecycle — one DocumentSession per document: transactional open
 *                        (publish-last), one idempotent close for every phase
 *   start / destroy    — explicit status machine; destroy closes everything
 *
 * The kernel closes every handle it opened; it never destroys the engine —
 * ownership follows acquisition, and the engine was handed in by the caller.
 */
export function createKernel(config: {
  engine: Engine;
  plugins: AnyPlugin[];
  /** The viewer's own settings, over `VIEWER_DEFAULTS`: what `resetSettings()` goes back to. */
  settings?: DeepPartial<ViewerSettings>;
  /** Observability seam: teardown, listener and join failures land here. Default: console.error. */
  report?: (error: unknown) => void;
  /**
   * The host's time: what plugins' `ctx.clock` schedules on. A browser passes
   * `browserClock()` from `@embedpdf/web`, for frames. Default: `timerClock`,
   * timers and no frames.
   */
  clock?: HostClock;
  /**
   * The host's print dialog: where `documents.print()` sends the pages. A browser passes
   * `browserPrinter()` from `@embedpdf/web`. Without one, nothing prints (`canPrint()` is false).
   */
  printer?: HostPrinter;
}): Kernel {
  const { engine, plugins } = config;
  const report = config.report ?? ((error: unknown) => console.error('[kernel]', error));
  const store = createStore(report);
  const plan = planPlugins(plugins);
  const documentScopedPlugins = plan.ordered.filter(isDocumentScoped);

  const workspaceCapabilities = new Map<CapabilityToken<unknown>, unknown>();
  const workspaceLeases = new Map<AnyPlugin, SliceLease<unknown>>();
  const workspaceConnectors = new Map<AnyPlugin, () => void>();
  const workspaceCancel = new AbortController();
  const workspaceScope = createScope(report);
  /** How each workspace capability looks from inside a document's scope, by token. The
   *  documents capability is built in, so its view is declared here; plugins declare theirs. */
  const inScopeByToken = new Map<CapabilityToken<unknown>, NonNullable<AnyPlugin['inScope']>>([
    [DocumentsToken, documentsInScope],
  ]);
  for (const plugin of plan.ordered) {
    if (plugin.token && plugin.inScope && !isDocumentScoped(plugin)) {
      inScopeByToken.set(plugin.token, plugin.inScope);
    }
  }

  // ── lifecycle events (the kernel primitive; disposed at destroy) ──────────
  const opened = createEventHook<DocumentOpenedEvent>(report);
  const openFailed = createEventHook<DocumentOpenFailedEvent>(report);
  const locked = createEventHook<DocumentLockedEvent>(report);
  const closed = createEventHook<DocumentClosedEvent>(report);
  const activeChanged = createEventHook<DocumentActiveChangedEvent>(report);
  const pagesChanged = createEventHook<DocumentPagesChangedEvent>(report);
  const unsavedChangesChanged = createEventHook<DocumentUnsavedChangesChangedEvent>(report);
  workspaceScope.defer(() => {
    for (const hook of [
      opened,
      openFailed,
      locked,
      closed,
      activeChanged,
      pagesChanged,
      unsavedChangesChanged,
    ])
      hook.dispose();
  });
  /** Every core write goes through here so an active-tab change is observed exactly once. */
  const setCore = (patch: Partial<CoreState>): void => {
    const before = store.getCore().activeId;
    store.setCore(patch);
    const after = store.getCore().activeId;
    if (before !== after) activeChanged.emit({ documentId: after, previousDocumentId: before });
  };
  const sessions = new Map<string, DocumentSession>();

  let status: KernelStatus = 'created';
  let startPromise: Promise<void> | null = null;
  let destroyPromise: Promise<void> | null = null;

  const guardUsable = (what: string) => {
    if (status === 'failed' || status === 'destroying' || status === 'destroyed') {
      throw new Error(`[kernel] ${what} on a ${status} kernel`);
    }
  };

  // ── sessions ─────────────────────────────────────────────────────────────────

  const checkpoint = (session: DocumentSession) => {
    if (session.cancel.signal.aborted) {
      throw new CancelledError(`closed while opening: ${session.id}`);
    }
  };

  /**
   * Await an engine/network call under the session's cancellation:
   *   - the call is retained so close() can abort real worker-side work
   *     (`AbortablePromise`), and
   *   - the await races the cancellation, so close()'s join never blocks on a
   *     call that cannot be aborted (a plain-promise engine, a stuck fetch).
   * When cancellation wins but the call later lands anyway, `onLateResult`
   * routes the result into the session scope — whose late-defer rule runs it
   * immediately after disposal — so a late-arriving resource cannot leak.
   * (Plugin inits are deliberately not raced: they are first-party code that
   * close() joins to completion; only unbounded external waits are raced.)
   */
  async function engineCall<T>(
    session: DocumentSession,
    call: Promise<T>,
    onLateResult?: (value: T) => void | Promise<void>,
  ): Promise<T> {
    const abortable = call as Promise<T> & { abort?: (reason?: unknown) => void };
    session.engineOp = typeof abortable.abort === 'function' ? (abortable as never) : null;
    const signal = session.cancel.signal;
    let onAbort: (() => void) | undefined;
    const cancellation = new Promise<never>((_, reject) => {
      onAbort = () => reject(new CancelledError(`closed while opening: ${session.id}`));
      if (signal.aborted) onAbort();
      else signal.addEventListener('abort', onAbort, { once: true });
    });
    try {
      return await Promise.race([call, cancellation]);
    } catch (error) {
      if (isCancelled(error)) {
        void call.then(
          (value) => {
            if (onLateResult) session.scope.defer(() => onLateResult(value));
          },
          () => {}, // the abandoned call's own rejection is not separately actionable
        );
      }
      throw error;
    } finally {
      if (onAbort) signal.removeEventListener('abort', onAbort);
      session.engineOp = null;
    }
  }

  function createSession(id: string, name: string | undefined): DocumentSession {
    const cancel = new AbortController();
    const session: DocumentSession = {
      id,
      instanceId: `${id}#${++instanceCounter}`,
      name,
      source: null,
      openOptions: undefined,
      phase: 'opening',
      handle: null,
      stagedMeta: null,
      scope: createScope(report),
      operation: null,
      engineOp: null,
      cancel,
      signal: cancel.signal,
      capabilities: new Map(),
      building: new Set(),
      views: new Map(),
      connectors: new Map(),
      leases: new Map(),
      settleFlushes: new Set(),
      downloadWraps: [],
      printWraps: [],
      changes: createDocumentChanges({
        handle: () => session.handle,
        notify: () => store.notify(),
        report,
      }),
      changeCount: 0,
      changesSeen: 0,
      close: () => closeSession(session),
    };
    // A download waits for every change: open holds are sent, and the answers awaited.
    session.settleFlushes.add(() => session.changes.settle());
    session.scope.defer(() => session.changes.close());
    return session;
  }

  /** One transition at a time per session (open, then possibly unlock). */
  function beginOperation<T>(session: DocumentSession, run: () => Promise<T>): Promise<T> {
    if (session.operation) {
      throw new Error(`[documents] "${session.id}" already has an active transition`);
    }
    const operation = run().finally(() => {
      if (session.operation === operation) session.operation = null;
    });
    session.operation = operation;
    return operation;
  }

  /** Atomic ticket → real-id reconciliation: the sessions map, the store slot,
   *  order position, and activation all move together, or not at all. */
  function rekeySession(session: DocumentSession, nextId: string): void {
    const previousId = session.id;
    if (previousId === nextId) return;
    const core = store.getCore();
    if (sessions.has(nextId) || core.documents[nextId] || core.pending[nextId]) {
      throw new PluginError('conflict', 'documents', `duplicate document id: ${nextId}`);
    }
    sessions.delete(previousId);
    session.id = nextId;
    sessions.set(nextId, session);
    session.views.clear(); // a view is bound to the id it was built for
    const slot = core.pending[previousId];
    if (slot) {
      const { [previousId]: _moved, ...pending } = core.pending;
      setCore({
        pending: { ...pending, [nextId]: { ...slot, id: nextId } },
        order: core.order.map((id) => (id === previousId ? nextId : id)),
        activeId: core.activeId === previousId ? nextId : core.activeId,
      });
    }
  }

  const closingSessions = new WeakMap<DocumentSession, Promise<void>>();
  function closeSession(session: DocumentSession): Promise<void> {
    const inFlight = closingSessions.get(session);
    if (inFlight) return inFlight;
    const closing = (async () => {
      session.phase = 'closing';
      unpublishSlot(session.id); // synchronous: the tab disappears now
      for (const lease of session.leases.values()) lease.revoke(); // write authority ends now
      // Cancel, join the producer, then drain its resources — in that order.
      // After the join, no known producer can register more resources; the
      // scope's late-defer rule covers anything unknowable.
      const reason = new CancelledError(`closed while opening: ${session.id}`);
      session.cancel.abort(reason);
      session.engineOp?.abort(reason);
      await session.operation?.catch((error) => {
        if (!isCancelled(error) && !isAbortLike(error)) report(error);
      });
      await session.scope.dispose();
      if (sessions.get(session.id) === session) sessions.delete(session.id);
      session.views.clear();
      closed.emit({ documentId: session.id });
    })();
    closingSessions.set(session, closing);
    return closing;
  }

  // ── store projection (publish/unpublish) ─────────────────────────────────────

  function nextActiveDocument(core: CoreState, removedId: string): string | null {
    if (core.activeId !== removedId) return core.activeId;
    const index = core.order.indexOf(removedId);
    const remaining = core.order.filter((id) => id !== removedId);
    return remaining.length === 0 ? null : (remaining[Math.max(0, index - 1)] ?? remaining[0]);
  }

  function publishPendingSlot(session: DocumentSession, activate: boolean): void {
    const core = store.getCore();
    setCore({
      pending: {
        ...core.pending,
        [session.id]: { id: session.id, name: session.name, status: 'loading' },
      },
      // A failed document opened again (`retry()`) keeps its place.
      order: core.order.includes(session.id) ? core.order : [...core.order, session.id],
      activeId: activate || core.activeId === null ? session.id : core.activeId,
    });
  }

  function publishLocked(session: DocumentSession, passwordProvided: boolean): void {
    const core = store.getCore();
    setCore({
      pending: {
        ...core.pending,
        [session.id]: { id: session.id, name: session.name, status: 'locked', passwordProvided },
      },
    });
    locked.emit({ documentId: session.id, passwordProvided });
  }

  function publishError(session: DocumentSession, error: unknown): void {
    const core = store.getCore();
    setCore({
      pending: {
        ...core.pending,
        [session.id]: { id: session.id, name: session.name, status: 'error', error },
      },
    });
    openFailed.emit({
      documentId: session.id,
      error: toPluginErrorInfo(toPluginError('documents', error)),
    });
  }

  function unpublishSlot(id: string): void {
    const core = store.getCore();
    if (!core.pending[id] && !core.documents[id]) return;
    const { [id]: _pending, ...pending } = core.pending;
    const { [id]: _document, ...documents } = core.documents;
    setCore({
      pending,
      documents,
      order: core.order.filter((other) => other !== id),
      activeId: nextActiveDocument(core, id),
    });
  }

  /** The one ready transition: swap the pending slot for the staged meta and
   *  announce `onOpened`. Everything before this is unpublished and rolls
   *  back by disposing the session scope; nothing after this can fail. */
  function commitReady(session: DocumentSession): void {
    session.phase = 'ready';
    const meta = session.stagedMeta!;
    const core = store.getCore();
    const { [session.id]: _resolved, ...pending } = core.pending;
    setCore({ documents: { ...core.documents, [session.id]: meta }, pending });
    opened.emit({ documentId: session.id, info: documentInfoOf(meta) });
  }

  /**
   * The document changed, or a download read every change it had: set `hasUnsavedChanges` and
   * announce a flip. Before the document is published, its staged meta carries the flag.
   */
  function setUnsavedChanges(session: DocumentSession, hasUnsavedChanges: boolean): void {
    const core = store.getCore();
    const published = core.documents[session.id];
    if (!published) {
      if (session.stagedMeta && session.stagedMeta.hasUnsavedChanges !== hasUnsavedChanges) {
        session.stagedMeta = { ...session.stagedMeta, hasUnsavedChanges };
      }
      return;
    }
    if (published.hasUnsavedChanges === hasUnsavedChanges) return;
    setCore({
      documents: { ...core.documents, [session.id]: { ...published, hasUnsavedChanges } },
    });
    unsavedChangesChanged.emit({ documentId: session.id, hasUnsavedChanges });
  }

  // ── capability resolution ────────────────────────────────────────────────────

  const sessionOf = (documentId?: string): DocumentSession | null => {
    const id = documentId ?? store.getCore().activeId;
    return id ? (sessions.get(id) ?? null) : null;
  };

  /** The handle plugins may touch: bring-up or ready — never locked, never
   *  a handle whose close already won. */
  const documentHandle = (documentId?: string): DocumentHandle | null => {
    const session = sessionOf(documentId);
    if (!session) return null;
    return session.phase === 'bringup' || session.phase === 'ready' ? session.handle : null;
  };

  /** The session a per-document verb acts on: `documentId`, or the active document. */
  function readySession(documentId: string | undefined, verb: string): DocumentSession {
    const session = sessionOf(documentId);
    if (!session || !documentHandle(session.id)) {
      throw new PluginError('not-ready', 'documents', `no open document to ${verb}`);
    }
    return session;
  }

  const allowsOn = (documentId: string | undefined, permission: Permission): boolean => {
    const handle = documentHandle(documentId);
    return handle ? sessionAllows(handle.security, permission) : false;
  };

  /**
   * Read the document's file, with everything the user sees: refuse without `doc.download`, let
   * it settle (what its plugins held back is sent and answered, settle.ts), then read it inside
   * every `aroundDownload` wrap (the document's own save actions). A read that saw every change
   * the document had clears `hasUnsavedChanges`; a change during the read, or after it (a
   * did-save script), keeps it. Closing the document, or `signal`, cancels it.
   */
  async function downloadFile(
    documentId: string | undefined,
    signal: AbortSignal | undefined,
    verb: string,
    read: (handle: DocumentHandle) => Promise<Uint8Array>,
    refuse?: (handle: DocumentHandle) => PluginError | null,
  ): Promise<Uint8Array> {
    const session = readySession(documentId, verb);
    if (!allowsOn(session.id, 'doc.download')) {
      throw permissionDenied('documents', 'doc.download', `documents.${verb}`);
    }
    const refusal = refuse?.(session.handle!);
    if (refusal) throw refusal;
    try {
      await settle(session.settleFlushes, [signal, session.signal], report);
      // The same document, even if another became active while it settled.
      const handle = documentHandle(session.id);
      if (!handle) throw new PluginError('not-ready', 'documents', `no open document to ${verb}`);
      let readAt = -1;
      const readFile = () => {
        readAt = session.changeCount;
        return cancellable('documents', signal, read(handle));
      };
      const bytes = await runWrapped(session.downloadWraps, readFile);
      if (readAt === session.changeCount) setUnsavedChanges(session, false);
      return bytes;
    } catch (error) {
      throw toPluginError('documents', error);
    }
  }

  // ── printing ─────────────────────────────────────────────────────────────

  const printer = config.printer ?? null;

  const canPrintOn = (documentId: string | undefined): boolean =>
    printer !== null && allowsOn(documentId, 'doc.print');

  /**
   * How a print comes out: the PDF copy with `doc.print.high`, a right to keep the copy (every
   * print dialog can save it as a file) and a printer that prints a PDF; else pictures, at the
   * resolution `doc.print.high` or `doc.print` allows.
   */
  const printQualityOf = (documentId: string | undefined): PrintQuality | null => {
    if (!canPrintOn(documentId)) return null;
    if (!allowsOn(documentId, 'doc.print.high')) return PRINT_STANDARD;
    const mayKeepCopy =
      allowsOn(documentId, 'doc.download') || allowsOn(documentId, 'doc.download.flattened');
    return mayKeepCopy && printer?.stagePdf ? PRINT_PDF : PRINT_HIGH;
  };

  /** The pages a print asks for, in its order: every page when it names none. */
  function printPagesOf(
    session: DocumentSession,
    pages: readonly PageRef[] | undefined,
  ): readonly PageInfo[] {
    const all = metaOf(session.id)?.pages ?? EMPTY_PAGES;
    if (pages === undefined) return all;
    if (pages.length === 0) {
      throw new PluginError('invalid-input', 'documents', 'a print needs at least one page');
    }
    const found = pages.map((ref) => {
      const page = findPage(all, ref);
      if (!page) {
        throw new PluginError(
          'not-found',
          'documents',
          `page ${ref.objectNumber} is not in this document`,
        );
      }
      return page;
    });
    if (new Set(found).size !== found.length) {
      throw new PluginError('invalid-input', 'documents', 'a print names a page twice');
    }
    return found;
  }

  /**
   * What prints beside the page content: the annotations as the options ask, by default when
   * the user may read them; the form fields whenever the user may read the form.
   */
  const printLayersOf = (documentId: string, options: PrintOptions) => ({
    includeAnnotations: options.includeAnnotations ?? allowsOn(documentId, 'doc.annotate.read'),
    includeFormFields: allowsOn(documentId, 'doc.forms.read'),
  });

  /**
   * Make the pages as they print and hand them to the printer, once the document settled: the
   * PDF copy, or a picture of each page. The pages are looked up again each time, so one deleted
   * meanwhile refuses `not-found`. Returns the staged print, how it came out, and the change it
   * saw last, so a print can tell it went stale.
   */
  async function stagePrint(
    session: DocumentSession,
    activePrinter: HostPrinter,
    quality: PrintQuality,
    options: PrintOptions,
  ): Promise<{ staged: StagedPrint; quality: PrintQuality; changesSeen: number }> {
    const { signal } = options;
    await settle(session.settleFlushes, [signal, session.signal], report);
    const handle = documentHandle(session.id);
    if (!handle) throw new PluginError('not-ready', 'documents', 'no open document to print');
    const changesSeen = session.changesSeen;
    const job: PrintJob = {
      handle,
      pages: printPagesOf(session, options.pages),
      layers: printLayersOf(session.id, options),
      name: session.name ?? 'document',
      options,
    };
    options.onProgress?.({ pagesRendered: 0, pageCount: job.pages.length });
    if (quality.kind === 'images') {
      return { staged: await stagePictures(job, activePrinter, quality.dpi), quality, changesSeen };
    }
    try {
      return { staged: await stagePdfCopy(job, activePrinter), quality, changesSeen };
    } catch (error) {
      // A printer can turn the PDF copy down (a browser that reports a PDF viewer it doesn't
      // show): the same pages print as pictures.
      if (signal?.aborted) throw error;
      const staged = await stagePictures(job, activePrinter, PRINT_HIGH.dpi);
      return { staged, quality: PRINT_HIGH, changesSeen };
    }
  }

  /** The PDF copy of the pages as they print, staged with the printer. */
  async function stagePdfCopy(job: PrintJob, activePrinter: HostPrinter): Promise<StagedPrint> {
    const { handle, pages, layers, name, options } = job;
    const { signal } = options;
    if (!activePrinter.stagePdf) {
      throw new PluginError('unsupported', 'documents', 'this printer prints no PDF');
    }
    const pdf = await cancellable(
      'documents',
      signal,
      handle.pages.extract(
        pages.map((page) => page.ref),
        { flatten: { usage: 'print' }, ...layers },
      ),
    );
    const staged = await activePrinter.stagePdf(pdf, { name, ...(signal ? { signal } : {}) });
    options.onProgress?.({ pagesRendered: pages.length, pageCount: pages.length });
    return staged;
  }

  /** A picture of each page, drawn by the print rules at `dpi`, staged with the printer. */
  async function stagePictures(
    job: PrintJob,
    activePrinter: HostPrinter,
    dpi: PrintDpi,
  ): Promise<StagedPrint> {
    const { handle, pages, layers, name, options } = job;
    const { signal } = options;
    const sheets: PrintSheet[] = [];
    for (const page of pages) {
      const image = await cancellable(
        'documents',
        signal,
        handle.page(page.ref).render.image({
          usage: 'print',
          viewport: { kind: 'dpi', dpi },
          format: 'png',
          ...layers,
        }),
      );
      const blob = await cancellable('documents', signal, image.blob());
      sheets.push({ image: blob, widthPt: page.size.width, heightPt: page.size.height });
      options.onProgress?.({ pagesRendered: sheets.length, pageCount: pages.length });
    }
    return activePrinter.stage(sheets, { name, ...(signal ? { signal } : {}) });
  }

  /**
   * Get a print ready. Refused before anything runs without `doc.print` or a printer, or for
   * pages the document doesn't have. Its `print()` runs inside every `aroundPrint` wrap (the
   * document's own print actions), and prepares again first when the document changed since:
   * a will-print action that fills in a date is on the paper. When the printer turns the PDF
   * copy down, preparing or printing, the same pages print as pictures, and `quality` says so.
   */
  async function preparePrint(
    documentId: string | undefined,
    options: PrintOptions = {},
  ): Promise<PreparedPrint> {
    const session = readySession(documentId, 'preparePrint');
    if (!allowsOn(session.id, 'doc.print')) {
      throw permissionDenied('documents', 'doc.print', 'documents.preparePrint');
    }
    const quality = printQualityOf(session.id);
    if (!printer || !quality) {
      throw new PluginError(
        'unsupported',
        'documents',
        'no printer: pass one to createKernel({ printer }), such as browserPrinter() from @embedpdf/web',
      );
    }
    const pageCount = printPagesOf(session, options.pages).length;
    try {
      let {
        staged,
        changesSeen,
        quality: printed,
      } = await stagePrint(session, printer, quality, options);
      let disposed = false;
      const dispose = () => {
        if (disposed) return;
        disposed = true;
        staged.dispose();
      };
      session.scope.defer(dispose);
      /** Stage the print again, as `as`, in place of what was staged. */
      const restage = async (as: PrintQuality, signal: AbortSignal | undefined) => {
        const fresh = await stagePrint(session, printer, as, {
          ...(options.pages ? { pages: options.pages } : {}),
          ...(options.includeAnnotations !== undefined
            ? { includeAnnotations: options.includeAnnotations }
            : {}),
          ...(signal ? { signal } : {}),
        });
        staged.dispose();
        ({ staged, changesSeen, quality: printed } = fresh);
      };
      return {
        get quality() {
          return printed;
        },
        pageCount,
        needsTap: printer.needsTap === true,
        async print(printOptions) {
          if (disposed) {
            throw new PluginError('invalid-input', 'documents', 'this print was disposed');
          }
          const signal = printOptions?.signal;
          const run = async () => {
            if (session.changesSeen !== changesSeen) await restage(quality, signal);
            if (signal?.aborted) {
              throw new PluginError('operation-cancelled', 'documents', 'print cancelled', {
                cause: signal.reason,
              });
            }
            try {
              await staged.print();
            } catch (error) {
              if (printed.kind !== 'pdf') throw error;
              await restage(PRINT_HIGH, signal);
              await staged.print();
            }
          };
          try {
            await runWrapped(session.printWraps, run);
          } catch (error) {
            throw toPluginError('documents', error);
          }
        },
        dispose,
      };
    } catch (error) {
      throw toPluginError('documents', error);
    }
  }

  /** Whether the plugin's `create()` is running for this document: it has no capability yet. */
  const isBuilding = (plugin: AnyPlugin, session: DocumentSession): boolean =>
    session.building.has(plugin) && !session.capabilities.has(plugin);

  function buildDocumentCapability(plugin: AnyPlugin, session: DocumentSession): unknown {
    let capability = session.capabilities.get(plugin);
    if (!capability) {
      // A second instance would take the first one's state slice and mirror cells, leaving the
      // connected one with cells it can no longer write.
      if (session.building.has(plugin)) {
        throw new PluginError(
          'not-ready',
          plugin.id,
          `"${plugin.id}" was asked for while it is being created`,
        );
      }
      const ctx = createPluginContext(services, plugin, session, session.signal, session.scope);
      session.building.add(plugin);
      let created: ReturnType<AnyPlugin['create']>;
      try {
        created = plugin.create(ctx);
      } finally {
        session.building.delete(plugin);
      }
      const { api, connect } = created;
      capability = api;
      session.connectors.set(plugin, () => {
        connect?.();
        markConnected(ctx);
      });
      session.capabilities.set(plugin, capability);
    }
    return capability;
  }

  /**
   * A workspace capability as a document's scope sees it: the view its plugin declares
   * (`inScope`), built once per document and kept on the session, so it is the same object on
   * every call and goes when the document closes. Without a document, or for a document the
   * kernel doesn't know, it is the capability itself.
   */
  function workspaceViewOf<T>(
    token: CapabilityToken<T>,
    capability: T,
    documentId: string | undefined,
  ): T {
    const inScope = inScopeByToken.get(token);
    const session = documentId === undefined ? undefined : sessions.get(documentId);
    if (!inScope || !session) return capability;
    let view = session.views.get(token);
    if (view === undefined) {
      view = inScope(capability, session.id);
      session.views.set(token, view);
    }
    return view as T;
  }

  function resolveCapability<T>(token: CapabilityToken<T>, documentId?: string): T {
    guardUsable(`capability("${token.name}")`);
    const workspaceCapability = workspaceCapabilities.get(token);
    if (workspaceCapability) return workspaceViewOf(token, workspaceCapability as T, documentId);
    const provider = plan.providerOf(token);
    if (!provider) throw new Error(`No capability "${token.name}".`);
    const id = documentId ?? store.getCore().activeId;
    if (!id) throw new Error(`Capability "${token.name}" requires an active document.`);
    const session = sessions.get(id);
    if (!session) throw new Error(`Capability "${token.name}" unavailable: no document "${id}".`);
    if (session.phase === 'bringup' || session.phase === 'ready') {
      return buildDocumentCapability(provider, session) as T;
    }
    // Fail fast and truthfully: a loading/locked/error document has no
    // plugin instances yet. `useOptional*` adapters turn this into their
    // fallback; strict resolution surfaces the real state.
    const shown = session.phase === 'opening' ? 'loading' : session.phase;
    throw new Error(`Capability "${token.name}" unavailable: document "${id}" is ${shown}.`);
  }

  /** Internal total resolver: bring-up counts, so a plugin's `ctx.tryGet`
   *  works during its own document's init. */
  function tryResolveInternal<T>(token: CapabilityToken<T>, documentId?: string): T | null {
    if (status === 'destroying' || status === 'destroyed') return null;
    const workspaceCapability = workspaceCapabilities.get(token);
    if (workspaceCapability) return workspaceViewOf(token, workspaceCapability as T, documentId);
    const provider = plan.providerOf(token);
    if (!provider) return null;
    const session = sessionOf(documentId);
    if (!session || (session.phase !== 'bringup' && session.phase !== 'ready')) return null;
    if (isBuilding(provider, session)) return null;
    return buildDocumentCapability(provider, session) as T;
  }

  /** Public total resolver — see `Kernel.tryCapability`. `ready` only: the
   *  null→instance flip at commit time is the adapters' re-render signal. */
  function tryResolveCapability<T>(token: CapabilityToken<T>, documentId?: string): T | null {
    if (status === 'destroying' || status === 'destroyed') return null;
    const workspaceCapability = workspaceCapabilities.get(token);
    if (workspaceCapability) return workspaceViewOf(token, workspaceCapability as T, documentId);
    const provider = plan.providerOf(token);
    if (!provider) return null;
    const session = sessionOf(documentId);
    if (!session || session.phase !== 'ready') return null;
    if (isBuilding(provider, session)) return null;
    return buildDocumentCapability(provider, session) as T;
  }

  // ── settings ─────────────────────────────────────────────────────────────────
  // The viewer's own settings: one store, read when a document opens (its scope and identity)
  // and by every adapter that paints (the accent, the page).
  const viewerSettings = createSettingsStore<ViewerSettings>(
    { defaults: VIEWER_DEFAULTS, registered: config.settings, whole: VIEWER_WHOLE_SETTINGS },
    store.notify,
    report,
  );
  workspaceScope.defer(() => viewerSettings.dispose());

  // A plugin's settings belong to the plugin as the app registered it, not to one document.
  // Each registration's store is built here, before any plugin is created, so the settings
  // can be read and changed before any document opens. Every instance of the plugin then
  // shares it, so a change reaches every open document and the ones opened later, and wakes
  // every reader through the store's one change stream.
  const settingsStores = new Map<AnyPlugin, SettingsStore<object>>();
  for (const plugin of plan.ordered) {
    if (plugin.settings) {
      settingsStores.set(plugin, createSettingsStore(plugin.settings, store.notify, report));
    }
  }
  // Destroy ends the listeners; the values stay readable, so a reader unmounting late never throws.
  workspaceScope.defer(() => {
    for (const settings of settingsStores.values()) settings.dispose();
  });

  function settingsOf<C>(token: CapabilityToken<C>): SettingsApi<SettingsOf<C>> {
    const provider = plan.providerOf(token);
    if (!provider) throw new Error(`No capability "${token.name}".`);
    const settings = settingsStores.get(provider);
    if (!settings) throw new Error(`Plugin "${provider.id}" has no settings.`);
    // The token's capability type names the settings type; the store was built untyped.
    return settings.api as unknown as SettingsApi<SettingsOf<C>>;
  }

  const services: ContextServices = {
    engine,
    store,
    workspaceScope,
    workspaceSignal: workspaceCancel.signal,
    workspaceLeases,
    report,
    clock: config.clock ?? timerClock,
    resolveCapability,
    tryResolveCapability: tryResolveInternal,
    documentHandle,
    settingsStoreOf: (plugin) => settingsStores.get(plugin),
  };

  // ── document lifecycle ───────────────────────────────────────────────────────

  // Tickets for slots whose real id isn't known yet (thunk sources).
  let ticketCounter = 0;
  const nextTicket = () => `pending:${++ticketCounter}`;

  /** Slices, the registry's event subscription, and every plugin's
   *  construction and connection — every step's release deferred into the
   *  session scope, every await followed by a checkpoint. Runs entirely
   *  pre-commit: a failure anywhere rolls the whole session back and the
   *  document was never `ready`. */
  async function bringUp(
    session: DocumentSession,
    snapshot: { pageCount: number; pages: DocumentMeta['pages'] },
  ): Promise<void> {
    session.phase = 'bringup';
    // The render policy is a document fact (Pattern A, like the page
    // registry): async on the engine contract, materialized once here —
    // pre-publish — so every consumer reads it synchronously off the meta
    // and no "policy still resolving" state exists anywhere downstream.
    // Best-effort by design: no render service, or a failed read, means
    // `continuous` — a policy hiccup must never block a document open.
    let renderPolicy: EngineRenderPolicy = CONTINUOUS_RENDER_POLICY;
    try {
      renderPolicy = (await session.handle!.render?.getPolicy()) ?? CONTINUOUS_RENDER_POLICY;
    } catch {
      /* unreachable policy = continuous */
    }
    checkpoint(session);
    session.stagedMeta = {
      id: session.id,
      instanceId: session.instanceId,
      name: session.name,
      pageCount: snapshot.pageCount,
      pages: snapshot.pages,
      revision: 0,
      renderPolicy,
      hasUnsavedChanges: false,
    };

    // Changes are unsaved only where they live in this tab until a download (the local
    // engine); the cloud engine stores each one as it's made.
    const tracksChanges = isLocalDocument(session.handle!);
    // Document mutation events (rotate/move/delete) replace the page
    // registry in place — the snapshot they carry is byte-identical to
    // pages.list(), so this is a direct swap, no merge. Own mutations and
    // remote (collaborator) mutations arrive identically; the handler is
    // origin-agnostic, as the event model intends.
    // The kernel listens first and last, so a change's events land as one store update.
    const bursts = createBurstGate(store);
    session.scope.defer(bursts.close);
    const unsubscribeEvents = session.handle!.events.subscribe((event) => {
      bursts.first(event);
      if (changesDocument(event)) {
        session.changesSeen += 1;
        if (tracksChanges) {
          session.changeCount += 1;
          setUnsavedChanges(session, true);
        }
      }
      const layout = layoutFromEvent(event);
      if (!layout) return;
      const now = store.getCore();
      const existing = now.documents[session.id];
      if (!existing) return; // pre-commit or closed — registry not published
      const updated: DocumentMeta = {
        ...existing,
        pageCount: layout.pageCount,
        pages: layout.pages,
        revision: existing.revision + 1,
      };
      setCore({ documents: { ...now.documents, [session.id]: updated } });
      pagesChanged.emit({
        documentId: session.id,
        revision: updated.revision,
        pages: updated.pages,
      });
    });
    session.scope.defer(unsubscribeEvents);

    for (const plugin of documentScopedPlugins) {
      // The lease is the write authority for this instance's slice. Revoking it
      // is the first teardown to run at close (LIFO), synchronously, so nothing
      // retained by this instance can reach a reopened document's state.
      const lease = store.lease(
        sliceKey(plugin.id, session.id),
        initialStateOf(plugin),
        session.instanceId,
      );
      session.leases.set(plugin, lease);
      session.scope.defer(() => lease.revoke()); // LIFO ⇒ reverse dependency order
    }
    // Construction and connection are part of the transaction (either can
    // throw); the callbacks they register fire post-commit and are isolated
    // by the store instead. Eager, in dependency order, with the store's change
    // stream held: a `create()` writes state, and a listener told of it at once
    // could read a plugin that isn't built yet and build it out of order,
    // before the plugins it finds while it's created. Listeners hear of the
    // whole bring-up in one pass, once every plugin is there.
    const release = store.hold();
    try {
      for (const plugin of documentScopedPlugins) {
        buildDocumentCapability(plugin, session);
        session.connectors.get(plugin)?.();
      }
    } finally {
      release();
    }
    session.scope.defer(session.handle!.events.subscribe((event) => bursts.last(event)));
    checkpoint(session);
  }

  /** What `open()` and `retry()` resolve: the document as its tab shows it, ready or locked. */
  function openedResult(session: DocumentSession): OpenDocumentResult {
    const core = store.getCore();
    const entry = core.documents[session.id] ?? core.pending[session.id];
    if (!entry) throw new PluginError('instance-closed', 'documents', `${session.id} was closed`);
    return { document: documentInfoOf(entry) };
  }

  // `async` on purpose: a refused reservation (duplicate id, destroyed kernel)
  // is a rejection, never a synchronous throw, like every other open failure.
  async function openDocument(
    input: OpenSource,
    options?: OpenDocumentOptions,
    slotId?: string,
  ): Promise<OpenDocumentResult> {
    const signal = options?.signal;
    if (signal?.aborted) {
      throw new PluginError('operation-cancelled', 'documents', 'the open was cancelled');
    }
    try {
      const { session, done } = reserveAndOpen(input, options, slotId);
      // Cancelling closes the document while it opens; once it's open, the signal is spent.
      const cancel = () => void session.close();
      signal?.addEventListener('abort', cancel, { once: true });
      try {
        return openedResult(await done);
      } finally {
        signal?.removeEventListener('abort', cancel);
      }
    } catch (error) {
      throw toPluginError('documents', error);
    }
  }

  /**
   * The engine's open options for a document: its own, and the viewer's `scope` and
   * `identity` where it has none. A document's own replace the viewer's, never merge.
   */
  function engineOptionsOf(options: OpenDocumentOptions | undefined) {
    const { activate: _activate, name: _name, signal: _signal, ...own } = options ?? {};
    const viewer = viewerSettings.api.getSettings();
    const scope = own.scope ?? viewer.scope ?? undefined;
    const identity = own.identity ?? viewer.identity ?? undefined;
    return {
      ...own,
      ...(scope !== undefined ? { scope } : {}),
      ...(identity !== undefined ? { identity } : {}),
    };
  }

  /**
   * Reserve the tab slot synchronously and start the open; returns the slot id at once.
   * `slotId` is a failed document's tab, which `retry()` opens again in place.
   */
  function reserveAndOpen(
    input: OpenSource,
    options?: OpenDocumentOptions,
    slotId?: string,
  ): { session: DocumentSession; done: Promise<DocumentSession> } {
    guardUsable('documents.open()');
    const engineOptions = engineOptionsOf(options);

    // 1. Reserve the tab slot synchronously (before the first await): id,
    //    order position, and activation are decided at request time; only the
    //    content arrives at completion time. Fire-and-forget concurrent opens
    //    therefore keep call order as tab order.
    const requestedId =
      slotId ?? (typeof input === 'function' ? nextTicket() : (idOfInput(input) ?? nextTicket()));
    if (sessions.has(requestedId)) {
      throw new PluginError('conflict', 'documents', `document already open: ${requestedId}`);
    }
    const session = createSession(requestedId, options?.name);
    session.source = input;
    session.openOptions = options;
    sessions.set(session.id, session);
    publishPendingSlot(session, options?.activate ?? true);

    const done = beginOperation(session, async () => {
      try {
        const given =
          typeof input === 'function'
            ? await engineCall(session, Promise.resolve(input(session.cancel.signal)))
            : input;
        checkpoint(session);
        // A URL is downloaded here, under the loading tab; closing the tab stops the download.
        const source = isUrlSource(given)
          ? await engineCall(session, fetchUrlSource(given, session.cancel.signal))
          : given;
        checkpoint(session);
        const sourceId = idOfInput(source);
        if (sourceId) rekeySession(session, sourceId);

        // A handle that lands after close() won still gets closed — see engineCall.
        const handle = await engineCall(session, engine.open(source, engineOptions), (late) =>
          late.close(),
        );
        session.handle = handle;
        session.scope.defer(() => handle.close()); // paired at acquisition — no exit path leaks it
        checkpoint(session);
        if (handle.id !== session.id) rekeySession(session, handle.id);

        // 2. A password-locked handle parks here — before pages.list(), which
        //    would reject on a locked document. `documents.unlock()` finishes
        //    the job later. The prompt's `incorrect` says a supplied password
        //    was tried and rejected (drives the "incorrect" copy).
        const prompt = handle.security?.passwordPrompt;
        if (prompt?.state === 'required') {
          session.phase = 'locked';
          publishLocked(session, prompt.incorrect);
          return session;
        }

        const snapshot = await engineCall(session, handle.pages.list());
        checkpoint(session);
        await bringUp(session, snapshot);
        commitReady(session);
        return session;
      } catch (error) {
        // Close won the race: close() owns unpublish + disposal; just get out
        // of its way, rejecting with the typed cancellation either way.
        if (isCancelled(error)) throw error;
        if (session.phase === 'closing' || isAbortLike(error)) {
          throw new CancelledError(`closed while opening: ${session.id}`);
        }
        // 3. Real failure: Rollback (scope releases exactly what was acquired,
        //    however far we got), then park the tab as `error` — closable, and
        //    reopenable after close. The document was never `ready`.
        await session.scope.dispose();
        session.phase = 'error';
        publishError(session, error);
        throw error;
      }
    });
    return { session, done };
  }

  async function unlockDocument(id: string, options: UnlockOptions): Promise<void> {
    guardUsable('documents.unlock()');
    const session = sessions.get(id);
    if (!session || session.phase !== 'locked' || !session.handle) {
      throw new PluginError('invalid-input', 'documents', `document is not locked: ${id}`);
    }
    const handle = session.handle;
    return beginOperation(session, async () => {
      // Engine-agnostic by design: local loads the parked worker bytes, cloud
      // POSTs /access — same call, same result. A wrong password rejects here
      // and nothing changes: the document stays locked, unlock is retryable,
      // and so does a password check the caller's signal stopped.
      try {
        await cancellable(
          'documents',
          options.signal,
          engineCall(session, handle.security.unlock({ password: options.password })),
        );
      } catch (error) {
        if (session.phase === 'closing' || isAbortLike(error)) {
          throw new CancelledError(`closed while opening: ${session.id}`);
        }
        throw error; // still locked — deliberately no state change
      }
      checkpoint(session);
      // Past the password: failures from here are real open failures — the
      // same rollback + `error` policy as the open path.
      try {
        const snapshot = await engineCall(session, handle.pages.list());
        checkpoint(session);
        await bringUp(session, snapshot);
        commitReady(session);
      } catch (error) {
        if (isCancelled(error)) throw error;
        if (session.phase === 'closing' || isAbortLike(error)) {
          throw new CancelledError(`closed while opening: ${session.id}`);
        }
        await session.scope.dispose();
        session.phase = 'error';
        publishError(session, error);
        throw error;
      }
    }).catch((error: unknown) => {
      throw toPluginError('documents', error);
    });
  }

  async function closeDocument(documentId: string): Promise<void> {
    const session = sessions.get(documentId);
    if (!session) return; // idempotent — unknown or already closed
    await session.close();
  }

  function reorder(next: string[]) {
    setCore({ order: next });
  }

  const metaOf = (documentId?: string): DocumentMeta | null => {
    const core = store.getCore();
    const id = documentId ?? core.activeId;
    return id ? (core.documents[id] ?? null) : null;
  };

  /** The tab list: the same array until one of its documents changes, or the order does. */
  let listMemo: { core: CoreState; value: readonly DocumentInfo[] } | null = null;
  const listDocuments = (): readonly DocumentInfo[] => {
    const core = store.getCore();
    if (listMemo?.core === core) return listMemo.value;
    const next = core.order.map((id) => documentInfoOf(core.documents[id] ?? core.pending[id]));
    const previous = listMemo?.value;
    const same =
      previous !== undefined &&
      previous.length === next.length &&
      previous.every((info, i) => info === next[i]);
    const value = same ? previous : Object.freeze(next);
    listMemo = { core, value };
    return value;
  };

  /** A document's fields: `documentId`, or the active document's. */
  const getDocument = (documentId?: string): DocumentInfo | null => {
    const core = store.getCore();
    const id = documentId ?? core.activeId;
    const entry = id ? (core.documents[id] ?? core.pending[id]) : undefined;
    return entry ? documentInfoOf(entry) : null;
  };

  const documents: DocumentsCapability = {
    open: openDocument,
    // A file's bytes are the engine's to take or refuse: it says which.
    canOpenFiles: () => engine.canOpenFiles,
    retry: async (id, options) => {
      const session = sessions.get(id);
      if (!session || session.phase !== 'error' || session.source === null) {
        throw new PluginError(
          'invalid-input',
          'documents',
          `${id} didn't fail to open; nothing to retry`,
        );
      }
      // In its own tab, which keeps its id and place; the active document stays the active one.
      // The failed session holds nothing (its scope was released when it failed), so the new
      // one takes its id without closing it: the tab never closes.
      const { source, openOptions } = session;
      sessions.delete(id);
      return openDocument(source, { ...openOptions, activate: false, signal: options?.signal }, id);
    },
    rename: (id, name) => {
      const core = store.getCore();
      if (core.documents[id]) {
        setCore({ documents: { ...core.documents, [id]: { ...core.documents[id], name } } });
      } else if (core.pending[id]) {
        setCore({ pending: { ...core.pending, [id]: { ...core.pending[id], name } } });
      }
      const session = sessions.get(id);
      if (session) session.name = name;
    },
    openAll: (initialDocuments) => {
      guardUsable('documents.openAll()');
      // Fire-and-forget on purpose: each open() reserves its tab slot
      // synchronously, so tabs exist immediately in array order; exactly one
      // activation, decided here at request time. Failures are tab state
      // (`error`/`locked`), never unhandled rejections.
      const activeIndex = Math.max(
        0,
        initialDocuments.findIndex((initialDocument) => initialDocument.active),
      );
      // The returned ids are the reserved slots: a thunk source's ticket is
      // rekeyed to the real id on resolve (`onOpened` carries the final id).
      return initialDocuments.map(({ source, active: _active, ...options }, index) => {
        try {
          const { session, done } = reserveAndOpen(source, {
            ...options,
            activate: index === activeIndex,
          });
          void done.catch(() => {});
          return session.id;
        } catch {
          // A refused reservation (an id already open) is not a boot failure:
          // the existing tab stands; report the id the caller asked for.
          return typeof source === 'function' ? '' : (idOfInput(source) ?? '');
        }
      });
    },
    unlock: unlockDocument,
    close: closeDocument,
    closeAll: async () => {
      for (const id of [...store.getCore().order]) await closeDocument(id);
    },
    setActive: (id) => {
      const core = store.getCore();
      // Pending tabs are selectable — a loading or locked tab is a real tab.
      if (core.documents[id] || core.pending[id]) setCore({ activeId: id });
    },
    getActiveId: () => store.getCore().activeId,
    getActive: () => getDocument(),
    list: listDocuments,
    get: getDocument,
    has: (id) => {
      const core = store.getCore();
      return core.documents[id] !== undefined || core.pending[id] !== undefined;
    },
    getCount: () => store.getCore().order.length,
    getOrder: () => store.getCore().order,
    setOrder: (ids) => {
      const current = store.getCore().order;
      const same =
        ids.length === current.length &&
        [...ids].sort().join('\0') === [...current].sort().join('\0');
      if (!same) {
        throw new PluginError(
          'invalid-input',
          'documents',
          'setOrder() needs a permutation of the current order',
        );
      }
      reorder([...ids]);
    },
    move: (id, toIndex) => {
      const core = store.getCore();
      if (!core.documents[id] && !core.pending[id]) return;
      const without = core.order.filter((documentId) => documentId !== id);
      const clamped = Math.max(0, Math.min(toIndex, without.length));
      without.splice(clamped, 0, id);
      reorder(without);
    },
    swap: (id, otherId) => {
      const core = store.getCore();
      const index = core.order.indexOf(id);
      const otherIndex = core.order.indexOf(otherId);
      if (index < 0 || otherIndex < 0) return;
      const next = [...core.order];
      next[index] = otherId;
      next[otherIndex] = id;
      reorder(next);
    },
    // Reading the file: download() and downloadLayer() (downloadFile above).
    download: (id, options) =>
      downloadFile(id, options?.signal, 'download', (handle) =>
        handle.download(options?.mode !== undefined ? { mode: options.mode } : undefined),
      ),
    downloadLayer: (id, options) =>
      downloadFile(
        id,
        options?.signal,
        'downloadLayer',
        (handle) => (isLocalDocument(handle) ? handle.downloadLayer() : Promise.reject(noLayer())),
        // Refused before anything runs: the cloud engine keeps layers itself.
        (handle) => (isLocalDocument(handle) ? null : noLayer()),
      ),
    // Printing it: the pages drawn by the print rules, on the host's printer (preparePrint above).
    preparePrint: (id, options) => preparePrint(id, options),
    async print(id, options = {}) {
      const prepared = await preparePrint(id, options);
      try {
        await prepared.print(options.signal ? { signal: options.signal } : undefined);
      } finally {
        prepared.dispose();
      }
    },
    getPrintQuality: (id) => printQualityOf(id),
    // The verbs that need them live here, so their checks do too (permissions.md).
    canDownload: (id) => allowsOn(id, 'doc.download'),
    canPrint: (id) => canPrintOn(id),
    // The page registry, addressed by PageRef (durable) or display index.
    listPages: (id) => metaOf(id)?.pages ?? EMPTY_PAGES,
    getPage: (page, id) => findPage(metaOf(id)?.pages ?? EMPTY_PAGES, page),
    getPageIndex: (ref, id) =>
      metaOf(id)?.pages.findIndex((pageInfo) => pageRefsEqual(pageInfo.ref, ref)) ?? -1,
    getRevision: (id) => metaOf(id)?.revision ?? -1,
    onOpened: opened.on,
    onOpenFailed: openFailed.on,
    onLocked: locked.on,
    onClosed: closed.on,
    onActiveChanged: activeChanged.on,
    onPagesChanged: pagesChanged.on,
    onUnsavedChangesChanged: unsavedChangesChanged.on,
  };
  workspaceCapabilities.set(DocumentsToken, documents);

  // ── workspace plugins: seed slices, then build their capabilities ────────────
  for (const plugin of plan.ordered) {
    if (!isDocumentScoped(plugin)) {
      workspaceLeases.set(plugin, store.lease(plugin.id, initialStateOf(plugin)));
    }
  }
  for (const plugin of plan.ordered) {
    if (isDocumentScoped(plugin)) continue;
    const ctx = createPluginContext(
      services,
      plugin,
      undefined,
      workspaceCancel.signal,
      workspaceScope,
    );
    const { api, connect } = plugin.create(ctx);
    if (plugin.token) workspaceCapabilities.set(plugin.token, api);
    workspaceConnectors.set(plugin, () => {
      connect?.();
      markConnected(ctx);
    });
  }

  return {
    ...viewerSettings.api,
    engine,
    documents,
    capability: resolveCapability,
    tryCapability: tryResolveCapability,
    scopeOf: plan.scopeOf,
    settingsOf,
    subscribe: store.subscribe,
    getState: store.getState,
    status: () => status,
    start: () => {
      if (status === 'destroying' || status === 'destroyed' || status === 'failed') {
        return Promise.reject(new Error(`[kernel] start() on a ${status} kernel`));
      }
      return (startPromise ??= (async () => {
        status = 'starting';
        try {
          for (const plugin of plan.ordered) {
            if (status !== 'starting') return; // destroy() raced us
            if (!isDocumentScoped(plugin)) workspaceConnectors.get(plugin)?.();
          }
          status = 'started';
        } catch (error) {
          // Startup failure unwinds everything construction + start registered;
          // the kernel is terminally failed (destroy() remains legal, and idle).
          status = 'failed';
          await workspaceScope.dispose();
          workspaceCapabilities.clear();
          throw error;
        }
      })());
    },
    destroy: () => {
      return (destroyPromise ??= (async () => {
        const wasFailed = status === 'failed';
        status = 'destroying'; // an in-flight start exits at its next check
        workspaceCancel.abort(new CancelledError('kernel destroyed'));
        await startPromise?.catch((error) => {
          if (!isCancelled(error) && !wasFailed) report(error);
        });
        // Close every session — the resource-owning map, not store.order: a
        // session mid-close is already unpublished but still needs joining.
        await Promise.allSettled([...sessions.values()].map((session) => session.close()));
        sessions.clear();
        await workspaceScope.dispose();
        workspaceCapabilities.clear();
        store.destroy();
        status = 'destroyed';
      })());
    },
  };
}

/**
 * A plugin's settings: what the app registered over the plugin's defaults, changed at runtime
 * with `updateSettings()`. A plugin declares them in its definition
 * (`definePlugin({ settings: { defaults, registered } })`), and the kernel builds one store per
 * plugin registration when it plans the plugin list. The store belongs to the registration, not
 * to a document: it exists before the first document opens, every instance of the plugin shares
 * it, and a change reaches every open document and the ones opened later. A plugin reads its
 * store with `ctx.settings()`; an adapter reads it with `kernel.settingsOf(token)`.
 *
 * Changes merge into the settings the same way everywhere (`registered` over the defaults, and
 * every `updateSettings()`): plain objects merge key by key, arrays and every other value
 * replace, and `undefined` leaves a setting as it is.
 */
import { createEventHook, type EventHook } from './event-hook';

/** A change to one setting: plain objects go deeper, arrays and functions are given whole. */
type DeepPartialValue<V> = V extends readonly unknown[] | ((...args: never[]) => unknown)
  ? V
  : V extends object
    ? DeepPartial<V>
    : V;

/** Every field optional, down through the plain objects. */
export type DeepPartial<T> = { readonly [K in keyof T]?: DeepPartialValue<T[K]> };

declare const noSettings: unique symbol;

/**
 * The settings of a plugin whose definition declares none. A type of its own rather than `never`:
 * a plugin list mixes plugins with and without settings, and `any` stands in for every type but
 * `never`.
 */
export interface NoSettings {
  readonly [noSettings]: true;
}

/** A plugin's settings as its definition declares them: `definePlugin({ settings })`. */
export interface SettingsDeclaration<T> {
  /** Every setting's value when the app registers none. */
  readonly defaults: T;
  /** What the app registered, usually the plugin factory's config: merged over `defaults`. */
  readonly registered?: DeepPartial<T> | undefined;
  /**
   * Top-level settings that are one value each, such as a person: a change replaces them
   * whole instead of merging into them, so nothing of the previous value stays.
   */
  readonly whole?: readonly (keyof T & string)[];
}

/** What `onSettingsChanged` carries: the settings after the change, and which of them changed. */
export interface SettingsChangedEvent<T> {
  readonly settings: T;
  /** The top-level settings whose value changed (`['highlight']` when only a highlight color did). */
  readonly changed: readonly (keyof T)[];
}

/** The four settings calls, spread into a plugin's capability. */
export interface SettingsApi<T> {
  /** The settings in effect: the same object until a setting changes. */
  getSettings(): T;
  /**
   * Merge `changes` into the settings, for every document: plain objects merge key by key,
   * arrays and other values replace, and `undefined` leaves a setting as it is. Fires
   * `onSettingsChanged` once when a setting changed.
   */
  updateSettings(changes: DeepPartial<T>): void;
  /** Go back to what the app registered (not to the plugin's defaults). Fires `onSettingsChanged` when a setting changed. */
  resetSettings(): void;
  /** Fires once for each call that changed a setting. */
  readonly onSettingsChanged: EventHook<SettingsChangedEvent<T>>;
}

/** The settings type of a capability that has the settings calls, else `never`. */
export type SettingsOf<Capability> = Capability extends { getSettings(): infer T } ? T : never;

/** What `ctx.settings()` returns: `get()` for the plugin's own code, `api` for its capability. */
export interface Settings<T> {
  /** The settings in effect. */
  get(): T;
  readonly api: SettingsApi<T>;
}

/** One registration's settings, kept by the kernel. */
export interface SettingsStore<T> {
  /** The calls themselves, bound to no instance: what `kernel.settingsOf(token)` hands out. */
  readonly api: SettingsApi<T>;
  /**
   * The store as one plugin instance sees it: the same settings, with an `onSettingsChanged`
   * of the instance's own. `cleanup` receives the teardown that ends it, so the instance's
   * listeners go when the instance closes; the settings stay.
   */
  forInstance(cleanup: (teardown: () => void) => void): Settings<T>;
  dispose(): void;
}

/**
 * Build a registration's store. `wake` runs after every change, before the event, so readers
 * that poll the capability (selectors over `getSettings()`) read again.
 */
export function createSettingsStore<T extends object>(
  { defaults, registered, whole = [] }: SettingsDeclaration<T>,
  wake: () => void,
  report: (error: unknown) => void,
): SettingsStore<T> {
  const initial = mergeSettings(defaults, registered, whole);
  let current = initial;
  const changedHook = createEventHook<SettingsChangedEvent<T>>(report);

  const commit = (next: T): void => {
    const changed = changedKeys(current, next);
    // A call that changes no value changes nothing: no wake, no event, the same object.
    if (changed.length === 0) return;
    current = next;
    wake();
    changedHook.emit({ settings: next, changed });
  };

  const api: SettingsApi<T> = {
    getSettings: () => current,
    updateSettings: (changes) => commit(mergeSettings(current, changes, whole)),
    resetSettings: () => commit(initial),
    onSettingsChanged: changedHook.on,
  };

  return {
    api,
    forInstance(cleanup) {
      const instanceChanged = createEventHook<SettingsChangedEvent<T>>(report);
      cleanup(changedHook.on((event) => instanceChanged.emit(event)));
      cleanup(() => instanceChanged.dispose());
      return {
        get: api.getSettings,
        api: { ...api, onSettingsChanged: instanceChanged.on },
      };
    },
    dispose: () => changedHook.dispose(),
  };
}

/**
 * `changes` merged into `settings`, the `whole` ones replaced instead: the merge every settings
 * store applies, for code that keeps changes before a store exists (an adapter whose engine is
 * still loading). What a change leaves as it was keeps its object, so a reader that compares by
 * reference sees only what really changed.
 */
export function mergeSettings<T>(
  settings: T,
  changes: DeepPartial<T> | undefined,
  whole: readonly string[] = [],
): T {
  if (whole.length === 0 || !isPlainObject(changes)) return mergeValue(settings, changes) as T;
  const merged = mergeValue(settings, omit(changes, whole)) as Record<string, unknown>;
  let replaced: Record<string, unknown> | null = null;
  for (const key of whole) {
    const change = (changes as Record<string, unknown>)[key];
    if (change === undefined || sameValue(merged[key], change)) continue;
    replaced ??= { ...merged };
    replaced[key] = change;
  }
  return (replaced ?? merged) as T;
}

/** `object` without `keys`. */
function omit(object: Record<string, unknown>, keys: readonly string[]): Record<string, unknown> {
  const rest: Record<string, unknown> = {};
  for (const key of Object.keys(object)) if (!keys.includes(key)) rest[key] = object[key];
  return rest;
}

function mergeValue(base: unknown, change: unknown): unknown {
  if (change === undefined) return base;
  // Arrays and other values replace; an equal one keeps the object already there.
  if (!isPlainObject(change)) return sameValue(base, change) ? base : change;
  const into = isPlainObject(base) ? base : {};
  let merged: Record<string, unknown> | null = null;
  for (const key of Object.keys(change)) {
    const current = hasOwn(into, key) ? into[key] : undefined;
    const next = mergeValue(current, change[key]);
    if (next === current) continue;
    merged ??= { ...into };
    merged[key] = next;
  }
  return merged ?? base;
}

/** The top-level settings whose value differs between `previous` and `next`. */
function changedKeys<T extends object>(previous: T, next: T): (keyof T)[] {
  const before = previous as Record<string, unknown>;
  const after = next as Record<string, unknown>;
  const keys = new Set([...Object.keys(before), ...Object.keys(after)]);
  return [...keys].filter((key) => !sameValue(before[key], after[key])) as (keyof T)[];
}

const isPlainObject = (value: unknown): value is Record<string, unknown> => {
  if (typeof value !== 'object' || value === null) return false;
  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
};

const hasOwn = (object: object, key: string): boolean =>
  Object.prototype.hasOwnProperty.call(object, key);

/** Equal by value: the same primitive or object, or arrays and plain objects with equal entries. */
function sameValue(left: unknown, right: unknown): boolean {
  if (Object.is(left, right)) return true;
  if (Array.isArray(left) && Array.isArray(right)) {
    return (
      left.length === right.length && left.every((item, index) => sameValue(item, right[index]))
    );
  }
  if (isPlainObject(left) && isPlainObject(right)) {
    const keys = Object.keys(left);
    return (
      keys.length === Object.keys(right).length &&
      keys.every((key) => hasOwn(right, key) && sameValue(left[key], right[key]))
    );
  }
  return false;
}

/**
 * @embedpdf/core/testing — a real plugin context for plugin unit tests, so a
 * suite never re-invents the kernel: the kernel's own store, state cell,
 * mirrors and event hooks, page geometry from a page list, capabilities from
 * a token map, cleanups you can run, and a document handle you shape per
 * test. Everything a controller reaches for behaves as in the kernel, minus
 * the engine.
 *
 *   const ctx = createTestContext({
 *     id: 'measurement',
 *     state: initialMeasurementState(),
 *     pages: [{ ref: toPageRef(1), size: { width: 600, height: 800 } }],
 *     capabilities: [[AnnotationToken, fakeAnnotation]],
 *     doc: { security: { allows: () => true } },
 *   });
 *   const api = ctx.connect(createMeasurementController(ctx));
 *   ctx.emitDocumentEvent(event); // folds into the plugin's mirrors
 *
 * Time is the host's timers unless a test passes a clock: `manualClock()`
 * steps timers and frames by hand.
 *
 *   const time = manualClock();
 *   const ctx = createTestContext({ clock: time.clock });
 *   time.advance(300); // timers due by then run
 *   time.frame(16); // and the callbacks waiting for a frame
 */
import type {
  Change,
  DocumentEvent,
  DocumentHandle,
  Engine,
  PageLayout,
  PageRef,
  PdfRect,
} from '@embedpdf/engine-core/runtime';
import { pageRefsEqual, subscribeToType } from '@embedpdf/engine-core/runtime';

/** Brand a fake engine or handle as local (`[LOCAL_ENGINE_BRAND]: true`) so
 *  `isLocalEngine` and `isLocalDocument` accept it. */
export { LOCAL_ENGINE_BRAND } from '@embedpdf/engine-core/runtime';

import { createBurstGate } from './bursts';
import { createDocumentChanges } from './changes';
import { instanceClock, timerClock, type Cancel, type HostClock } from './clock';
import { PluginError } from './errors';
import { createEventHook } from './event-hook';
import { createLatestLane, type LatestLane } from './lanes';
import { createMirror, type MirrorController, type MirrorEnvironment } from './mirror';
import { createPageMirror } from './page-mirror';
import { createSerialQueue, type SerialQueue } from './serial-queue';
import { cancellable } from './cancellable';
import { findPage, pageOf } from './page-of';
import { runWrapped, type DownloadWrap, type PrintWrap } from './context';
import { fieldPermissionDenied, permissionDenied, sessionAllows } from './permissions';
import { createSettingsStore, type NoSettings, type SettingsDeclaration } from './settings';
import { settle, type SettleFlush } from './settle';
import { createStore } from './store';
import {
  DocumentsToken,
  type CapabilityToken,
  type DocumentInfo,
  type DocumentMeta,
  type DocumentsCapability,
  type OperationOptions,
  type PluginContext,
  type Unsubscribe,
} from './types';

export interface TestPage {
  readonly ref: PageRef;
  /** Page size in points (default 612 × 792, or the crop's extent); the crop box is `[0, 0, w, h]` unless given. */
  readonly size?: { readonly width: number; readonly height: number };
  readonly crop?: PdfRect;
  readonly rotation?: PageLayout['rotation'];
  readonly userUnit?: number;
  readonly label?: string | null;
}

export interface TestContextOptions<S, T extends object = NoSettings> {
  /** The plugin id (`ctx.id`, error prefixes). Default `'test'`. */
  readonly id?: string;
  /** The instance's initial state; omit for a stateless plugin. */
  readonly state?: S;
  /**
   * The plugin's settings, as its definition declares them; `ctx.settings()` reads them.
   * Without them the context has none, and `ctx.settings()` throws.
   */
  readonly settings?: SettingsDeclaration<T>;
  /** The document's pages; `document()` and `geometry` derive from them. */
  readonly pages?: readonly TestPage[];
  readonly documentId?: string;
  /** Capabilities `get`/`tryGet` resolve, by token. `DocumentsToken` defaults to a
   *  registry holding this one document. */
  readonly capabilities?: ReadonlyArray<readonly [CapabilityToken<unknown>, unknown]>;
  /** The document handle members the test exercises (`security`, `page`, `events`, …),
   *  or a real engine document; `null` for a workspace plugin with no document. */
  readonly doc?: Partial<DocumentHandle> | null;
  readonly engine?: Partial<Engine>;
  /** The host's time (`ctx.clock`). Default: `timerClock`, the environment's timers and no frames. */
  readonly clock?: HostClock;
}

export interface TestContext<S, T extends object = NoSettings> extends PluginContext<S, T> {
  /** Every capability `get` can resolve — add or replace during a test. */
  readonly capabilities: Map<CapabilityToken<unknown>, unknown>;
  /** Observe the change stream: state updates and `notify` wake the listener. */
  subscribe(listener: () => void): Unsubscribe;
  /**
   * What the kernel does after `create`: run the instance's `connect`, then
   * start its mirrors' first loads. Returns the instance's api.
   */
  connect<C>(instance: { api: C; connect?: () => void }): C;
  /** Deliver a confirmed document event, as the engine would (the default `doc.events`). */
  emitDocumentEvent(event: DocumentEvent): void;
  /** What `documents.download()` does first: run every `onSettle` flush and wait for it (settle.ts). */
  settle(signal?: AbortSignal): Promise<void>;
  /**
   * What `documents.download()` does after settling: `read` the file inside every
   * `aroundDownload` wrap, the first registered outermost.
   */
  download(read: () => Promise<Uint8Array>): Promise<Uint8Array>;
  /**
   * What a print does around the print dialog: `print` inside every `aroundPrint` wrap, the
   * first registered outermost.
   */
  print(print: () => Promise<void>): Promise<void>;
  /** Run the registered cleanups and abort the lifetime (the plugin's unmount). */
  dispose(): Promise<void>;
}

const layoutOf = (page: TestPage, index: number): PageLayout => {
  // Size follows the crop when only the crop is given, and vice versa.
  const size =
    page.size ??
    (page.crop
      ? { width: page.crop.right - page.crop.left, height: page.crop.top - page.crop.bottom }
      : { width: 612, height: 792 });
  const crop = page.crop ?? { left: 0, bottom: 0, right: size.width, top: size.height };
  // Every box is the crop box, measured from its own top-left corner.
  const visible = { x: 0, y: 0, width: crop.right - crop.left, height: crop.top - crop.bottom };
  return {
    index,
    ref: page.ref,
    label: page.label ?? null,
    size,
    rotation: page.rotation ?? 0,
    userUnit: page.userUnit ?? 1,
    tabOrder: null,
    boxes: {
      media: { ...visible },
      crop: { ...visible },
      bleed: { ...visible },
      trim: { ...visible },
      art: { ...visible },
    },
    pdfCropBox: crop,
  };
};

/** A read-only document registry holding the test's one document. */
function testDocuments(meta: DocumentMeta): DocumentsCapability {
  const info: DocumentInfo = {
    id: meta.id,
    status: 'ready',
    pageCount: meta.pageCount,
    hasUnsavedChanges: false,
  };
  const known = (id?: string) => id === undefined || id === meta.id;
  const pagesOf = (id?: string) => (known(id) ? meta.pages : []);
  const unsupported = (verb: string) => () => {
    throw new PluginError('unsupported', 'documents', `${verb} is not available in a test context`);
  };
  const never = () => () => {};
  return {
    getActiveId: () => meta.id,
    getActive: () => info,
    list: () => [info],
    get: (id) => (known(id) ? info : null),
    has: (id) => known(id),
    getCount: () => 1,
    getOrder: () => [meta.id],
    listPages: pagesOf,
    getPage: (page, id) => findPage(pagesOf(id), page),
    getPageIndex: (ref, id) => pagesOf(id).findIndex((page) => pageRefsEqual(page.ref, ref)),
    getRevision: (id) => (known(id) ? meta.revision : -1),
    canDownload: () => true,
    // A test context has no printer.
    canPrint: () => false,
    getPrintQuality: () => null,
    // A test context opens nothing.
    canOpenFiles: () => false,
    open: unsupported('open'),
    retry: unsupported('retry'),
    rename: unsupported('rename'),
    openAll: unsupported('openAll'),
    unlock: unsupported('unlock'),
    close: unsupported('close'),
    closeAll: unsupported('closeAll'),
    setActive: unsupported('setActive'),
    setOrder: unsupported('setOrder'),
    move: unsupported('move'),
    swap: unsupported('swap'),
    download: unsupported('download'),
    downloadLayer: unsupported('downloadLayer'),
    preparePrint: unsupported('preparePrint'),
    print: unsupported('print'),
    onOpened: never,
    onOpenFailed: never,
    onLocked: never,
    onClosed: never,
    onActiveChanged: never,
    onPagesChanged: never,
    onUnsavedChangesChanged: never,
  } satisfies DocumentsCapability;
}

export function createTestContext<S = void, T extends object = NoSettings>(
  options: TestContextOptions<S, T> = {},
): TestContext<S, T> {
  const id = options.id ?? 'test';
  const documentId = options.documentId ?? 'doc';
  const report = (error: unknown) => console.error(`[${id}]`, error);
  const store = createStore(report);
  const instanceId = `${documentId}:${id}`;
  const lease = store.lease<S>(id, options.state as S, instanceId);
  const cleanups: Array<() => void | Promise<void>> = [];
  const lifetime = new AbortController();
  const settleFlushes = new Set<SettleFlush>();
  const downloadWraps: DownloadWrap[] = [];
  const printWraps: PrintWrap[] = [];
  const pages = (options.pages ?? []).map(layoutOf);
  const capabilities = new Map<CapabilityToken<unknown>, unknown>(options.capabilities ?? []);
  const documentEvents = createEventHook<DocumentEvent>(report);
  // A plain object lists the members a test fakes, over working defaults; a
  // real engine document (a class instance) is used as it is.
  const isRealHandle =
    options.doc != null && Object.getPrototypeOf(options.doc) !== Object.prototype;
  const doc =
    options.doc === null
      ? null
      : isRealHandle
        ? (options.doc as DocumentHandle)
        : fakeDocument({
            id: documentId,
            events: {
              subscribe: documentEvents.on,
              on: (type: DocumentEvent['type'], listener: (event: DocumentEvent) => void) =>
                subscribeToType(documentEvents.on, type, listener),
              lastServerId: () => null,
            },
            security: { allows: () => true, allowsAnnotation: () => true, allowsField: () => true },
            ...options.doc,
          });
  const requireDoc = (): DocumentHandle => {
    if (!doc) throw new PluginError('not-ready', id, 'the test context has no document');
    return doc;
  };
  // The document's change queue, as the kernel keeps one: `doc.apply` sends its changes.
  const changes = createDocumentChanges({ handle: () => doc, notify: store.notify, report });
  settleFlushes.add(() => changes.settle());
  cleanups.push(() => changes.close());
  const bursts = createBurstGate(store);
  const mirrors: MirrorController<unknown>[] = [];
  const mirrorEnvironment = (): MirrorEnvironment => ({
    doc: requireDoc(),
    changes,
    notify: store.notify,
    lifetime: lifetime.signal,
    cell(name, initial) {
      const cell = store.lease(`${id}/${name}`, initial, instanceId);
      lifetime.signal.addEventListener('abort', () => cell.revoke(), { once: true });
      return cell;
    },
    onDocumentEvent(listener) {
      cleanups.push(requireDoc().events.subscribe(listener));
    },
    report,
  });
  const meta: DocumentMeta = {
    id: documentId,
    instanceId,
    pageCount: pages.length,
    pages,
    revision: 1,
    renderPolicy: { kind: 'continuous' },
    hasUnsavedChanges: false,
  };
  if (!capabilities.has(DocumentsToken as CapabilityToken<unknown>)) {
    capabilities.set(DocumentsToken as CapabilityToken<unknown>, testDocuments(meta));
  }
  const notFound = (ref: PageRef) =>
    new PluginError('not-found', id, `page ${ref.objectNumber} is not in this document`);
  const resolve = <T>(token: CapabilityToken<T>): T | null =>
    capabilities.has(token as CapabilityToken<unknown>)
      ? (capabilities.get(token as CapabilityToken<unknown>) as T)
      : null;
  const require = <T>(token: CapabilityToken<T>): T => {
    const capability = resolve(token);
    if (capability === null) {
      throw new PluginError('not-found', id, `no capability for ${token.name} in the test context`);
    }
    return capability;
  };
  const queues = new Map<string, SerialQueue>();
  const lanes = new Map<string, LatestLane>();
  // The context is the plugin's only instance, so it holds the registration's settings itself.
  const settingsStore = options.settings
    ? createSettingsStore(options.settings, store.notify, report)
    : null;
  if (settingsStore) cleanups.push(() => settingsStore.dispose());
  const settings = settingsStore?.forInstance((teardown) => cleanups.push(teardown)) ?? null;

  const context: TestContext<S, T> = {
    id,
    instanceId: meta.instanceId,
    engine: (options.engine ?? {}) as Engine,
    documentId,
    get doc() {
      return doc as DocumentHandle;
    },
    documentHandle: () => doc,
    subscribe: store.subscribe,
    state: {
      get: () => lease.read(),
      update: (transition, ...args) => {
        lease.write(transition(lease.read(), ...args));
      },
      onChange: lease.onChange,
    },
    settings: () => {
      if (!settings) throw new Error(`[${id}] the test context declares no settings`);
      return settings;
    },
    notify: store.notify,
    watch: (select, handler, isEqual = Object.is) => {
      let previous = select();
      const off = store.subscribe(() => {
        const next = select();
        if (isEqual(previous, next)) return;
        const prior = previous;
        previous = next;
        handler(next, prior);
      });
      cleanups.push(off);
      return off;
    },
    mirror: (spec) => {
      const controller = createMirror(spec, mirrorEnvironment());
      mirrors.push(controller as MirrorController<unknown>);
      return controller.mirror;
    },
    pageMirror: (spec) => createPageMirror(spec, mirrorEnvironment()),
    changes: changes.forPlugin(id),
    document: () => meta,
    get: require,
    tryGet: resolve,
    forDocument: (token) => require(token),
    tryForDocument: (token) => resolve(token),
    cleanup: (fn) => {
      cleanups.push(fn);
    },
    clock: instanceClock(options.clock ?? timerClock, lifetime.signal),
    onSettle: (flush) => {
      settleFlushes.add(flush);
      cleanups.push(() => {
        settleFlushes.delete(flush);
      });
    },
    aroundDownload: (wrap) => {
      downloadWraps.push(wrap);
      cleanups.push(() => {
        const index = downloadWraps.indexOf(wrap);
        if (index >= 0) downloadWraps.splice(index, 1);
      });
    },
    aroundPrint: (wrap) => {
      printWraps.push(wrap);
      cleanups.push(() => {
        const index = printWraps.indexOf(wrap);
        if (index >= 0) printWraps.splice(index, 1);
      });
    },
    events: {
      source: <T>() => {
        const hook = createEventHook<T>((error) =>
          console.error(`[${id}] listener failed:`, error),
        );
        cleanups.push(() => hook.dispose());
        return hook;
      },
    },
    listen: (source, listener) => {
      const off = typeof source === 'function' ? source(listener) : source.subscribe(listener);
      cleanups.push(off);
    },
    waitFor: (predicate, waitOptions?: OperationOptions) =>
      new Promise<void>((resolveWait, reject) => {
        if (predicate()) return resolveWait();
        const off = context.subscribe(() => {
          if (!predicate()) return;
          off();
          resolveWait();
        });
        waitOptions?.signal?.addEventListener('abort', () => {
          off();
          reject(new PluginError('operation-cancelled', id, 'waitFor cancelled'));
        });
      }),
    serialQueue: (key = 'default') => {
      let queue = queues.get(key);
      if (!queue) {
        queue = createSerialQueue(id);
        queues.set(key, queue);
      }
      return queue;
    },
    latest: (key) => {
      let lane = lanes.get(key);
      if (!lane) {
        lane = createLatestLane(lifetime.signal, id, key);
        lanes.set(key, lane);
      }
      return lane;
    },
    acquire: async (get, dispose) => {
      const resource = await get(lifetime.signal);
      if (lifetime.signal.aborted) {
        await dispose(resource);
        throw new PluginError('instance-closed', id, 'acquired after close');
      }
      cleanups.push(() => dispose(resource));
      return resource;
    },
    assertPageRef: (ref) => {
      if (!pages.some((pageInfo) => pageRefsEqual(pageInfo.ref, ref))) throw notFound(ref);
    },
    getPage: (page) => findPage(pages, page),
    pageOf: (page) => pageOf(pages, page, id),
    allows: (permission) => sessionAllows(requireDoc().security, permission),
    assertAllowed: (permission, operation) => {
      if (!sessionAllows(requireDoc().security, permission)) {
        throw permissionDenied(id, permission, operation);
      }
    },
    allowsField: (action, field) =>
      requireDoc().security.allowsField(action, { groupId: field.groupId }),
    assertAllowedField: (action, field, operation) => {
      if (!requireDoc().security.allowsField(action, { groupId: field.groupId })) {
        throw fieldPermissionDenied(id, action, field, operation);
      }
    },
    cancellable: (signal, task) => cancellable(id, signal, task),
    capabilities,
    connect: (instance) => {
      instance.connect?.();
      for (const mirror of mirrors.splice(0)) mirror.start();
      return instance.api;
    },
    emitDocumentEvent: (event) => {
      bursts.first(event);
      documentEvents.emit(event);
      bursts.last(event);
    },
    settle: (signal) => settle(settleFlushes, [signal, lifetime.signal], report),
    download: (read) => runWrapped(downloadWraps, read),
    print: (print) => runWrapped(printWraps, print),
    dispose: async () => {
      lifetime.abort();
      for (const fn of cleanups.splice(0).reverse()) await fn();
    },
  };
  return context;
}

/** A clock a test steps by hand (see {@link manualClock}). */
export interface ManualClock {
  /** The clock to hand a test context or a kernel. */
  readonly clock: HostClock;
  /** The current time in milliseconds. It starts at 0. */
  readonly now: number;
  /** How many timers and frame callbacks are waiting. */
  readonly pending: { readonly timers: number; readonly frames: number };
  /** Move time forward by `ms`, running the timers that fall due, earliest first. */
  advance(ms: number): void;
  /**
   * Show a frame at `timeMs` (default: now): move time there, running the
   * timers due by then, and run the callbacks waiting for a frame. What they
   * schedule waits for the next frame.
   */
  frame(timeMs?: number): void;
}

/**
 * Time that moves only when the test moves it. `frames: false` gives a host
 * that never paints, as Node is.
 */
export function manualClock(options: { frames?: boolean } = {}): ManualClock {
  let now = 0;
  let order = 0;
  const timers = new Map<number, { due: number; run: () => void }>();
  const frames = new Map<number, (timeMs: number) => void>();

  const nextDue = (until: number): number | undefined => {
    let found: number | undefined;
    for (const [id, timer] of timers) {
      if (timer.due > until) continue;
      if (found === undefined || timer.due < timers.get(found)!.due) found = id;
    }
    return found;
  };
  const advanceTo = (target: number): void => {
    if (target < now) throw new Error(`manualClock: time does not go back (${target} < ${now})`);
    for (let id = nextDue(target); id !== undefined; id = nextDue(target)) {
      const timer = timers.get(id)!;
      timers.delete(id);
      now = timer.due;
      timer.run();
    }
    now = target;
  };

  const clock: HostClock = {
    now: () => now,
    after(ms, run): Cancel {
      const id = ++order;
      timers.set(id, { due: now + Math.max(0, ms), run });
      return () => void timers.delete(id);
    },
    ...(options.frames === false
      ? {}
      : {
          nextFrame(run: (timeMs: number) => void): Cancel {
            const id = ++order;
            frames.set(id, run);
            return () => void frames.delete(id);
          },
        }),
  };
  return {
    clock,
    get now() {
      return now;
    },
    get pending() {
      return { timers: timers.size, frames: frames.size };
    },
    advance: (ms) => advanceTo(now + ms),
    frame(timeMs = now) {
      advanceTo(timeMs);
      const due = [...frames.values()];
      frames.clear();
      for (const run of due) run(now);
    },
  };
}

/**
 * A faked document's members over the defaults every document has: calls'
 * facts and working sets change no result, so `with` gives the same fake and
 * a working set goes nowhere, unless the test fakes them.
 */
function fakeDocument(members: Record<string, unknown>): DocumentHandle {
  const fake: Record<string, unknown> = { setWorkingSet: () => {}, ...members };
  fake.with ??= () => fake;
  return fake as unknown as DocumentHandle;
}

/* ── gate: an engine that holds changes ─────────────────────────────────── */

/**
 * An engine whose documents hold every change until the test lets it go, so
 * a test sees what the reads show while a change is on its way: wrap a real
 * engine with `gate(engine)`, boot the kernel on `gate.engine`, set
 * `holding`, then `release()` or `refuse()` the oldest held change.
 */
/** A change a gate holds, with the promise its sender awaits. */
export interface GatedChange {
  readonly change: Change;
  readonly options: unknown;
  resolve(value: unknown): void;
  reject(error: unknown): void;
}

export interface Gate {
  readonly engine: Engine;
  /** The changes held so far, oldest first. */
  readonly held: GatedChange[];
  /** Whether changes are held; when not, they go straight to the engine. */
  holding: boolean;
  /** Send the oldest held change to the engine, and wait for its answer to land. */
  release(): Promise<void>;
  /** Refuse the oldest held change, as the engine would. */
  refuse(error: unknown): void;
}

export function gate(engine: Engine): Gate {
  const held: GatedChange[] = [];
  let inner: DocumentHandle | null = null;
  const state: Gate = {
    engine: null as unknown as Engine,
    held,
    holding: false,
    async release() {
      const next = held.shift();
      if (!next || !inner) throw new Error('nothing is held');
      await inner.apply(next.change, next.options as never).then(next.resolve, next.reject);
    },
    refuse(error) {
      const next = held.shift();
      if (!next) throw new Error('nothing is held');
      next.reject(error);
    },
  };
  const wrap = (doc: DocumentHandle): DocumentHandle =>
    new Proxy(doc, {
      get(target, prop) {
        if (prop === 'apply') {
          return (change: Change, options: unknown) =>
            state.holding
              ? new Promise((resolve, reject) => held.push({ change, options, resolve, reject }))
              : target.apply(change, options as never);
        }
        const value = Reflect.get(target, prop, target) as unknown;
        if (prop === 'with' && typeof value === 'function') {
          return (...args: unknown[]) => wrap(value.apply(target, args) as DocumentHandle);
        }
        return typeof value === 'function' ? value.bind(target) : value;
      },
    });
  (state as { engine: Engine }).engine = new Proxy(engine, {
    get(target, prop) {
      if (prop === 'open') {
        return async (...args: Parameters<Engine['open']>) => {
          const doc = await target.open(...args);
          inner = doc;
          return wrap(doc);
        };
      }
      const value = Reflect.get(target, prop, target) as unknown;
      return typeof value === 'function' ? value.bind(target) : value;
    },
  });
  return state;
}

import type { Unsubscribe } from './types';

/**
 * Subscribe-only face of a plugin event — the one event shape a capability
 * exposes (`onX: EventHook<XEvent>`). Events carry occurrences, never state:
 * a late subscriber that needs the current value uses a query + selector
 * instead. Payloads are plain serializable objects.
 */
export type EventHook<T> = (
  listener: (event: T) => void,
  options?: { signal?: AbortSignal },
) => Unsubscribe;

/**
 * The plugin-private pair behind one capability event. Expose `.on` on the
 * capability; keep `emit`/`dispose` inside the plugin. Because the capability
 * member is the bare function type, the emitting half is unreachable through
 * the public contract by construction.
 */
export interface EventHookSource<T> {
  readonly on: EventHook<T>;
  emit(event: T): void;
  dispose(): void;
}

/**
 * Create one capability event.
 *
 * Subscribe with `{ signal }` to tie the subscription to an AbortSignal; a
 * pre-aborted signal never registers.
 *
 * Delivery contract: synchronous fan-out over a snapshot of the listener set
 * (listeners added or removed during an emit don't affect that emit); a
 * throwing listener is isolated — reported through `onListenerError`, never
 * allowed to break the emitting operation or its sibling listeners. After
 * `dispose()`, `on` returns an inert unsubscribe (teardown races never throw).
 * No value cache, no replay, no equality — state belongs to the store.
 */
export function createEventHook<T = void>(
  onListenerError?: (error: unknown) => void,
): EventHookSource<T> {
  let listeners: Set<(event: T) => void> | null = new Set();
  return {
    on(listener, options) {
      if (!listeners || options?.signal?.aborted) return () => {};
      listeners.add(listener);
      const off = () => void listeners?.delete(listener);
      // An AbortSignal is the framework-neutral lifetime: one controller can
      // end many subscriptions (rule 8 of the contract).
      options?.signal?.addEventListener('abort', off, { once: true });
      return off;
    },
    emit(event) {
      if (!listeners) return;
      for (const listener of [...listeners]) {
        try {
          listener(event);
        } catch (error) {
          onListenerError?.(error);
        }
      }
    },
    dispose() {
      listeners = null;
    },
  };
}

/**
 * Shortcut parsing + matching — pure. No `navigator`: platform is an input
 * (`isMac`), decided by the embedder, same rule as plugin-i18n's locale.
 *
 * Grammar: modifiers and one key joined by '+', e.g. 'Mod+K', 'Ctrl+=',
 * 'Shift+Alt+D', 'Meta+NumpadAdd'. 'Mod' is ⌘ on mac and Ctrl elsewhere.
 * Keys longer than one character (F1, Escape, NumpadAdd, ArrowLeft) match
 * `event.key` or `event.code` case-insensitively, so numpad shortcuts work.
 */

export interface ParsedShortcut {
  readonly key: string; // lowercase
  readonly mod: boolean; // platform-resolved at match time
  readonly ctrl: boolean;
  readonly meta: boolean;
  readonly alt: boolean;
  readonly shift: boolean;
}

/** The subset of KeyboardEvent the matcher reads — keeps this module DOM-free. */
export interface KeyStroke {
  readonly key: string;
  readonly code?: string;
  readonly ctrlKey: boolean;
  readonly metaKey: boolean;
  readonly altKey: boolean;
  readonly shiftKey: boolean;
}

const MODIFIERS = new Set([
  'mod',
  'ctrl',
  'control',
  'meta',
  'cmd',
  'command',
  'alt',
  'option',
  'shift',
]);

export function parseShortcut(shortcut: string): ParsedShortcut {
  const tokens = shortcut.split('+').map((token) => token.trim());
  // 'Ctrl+=' splits to ['Ctrl', '', ''] — an empty tail means the key is '+'.
  const keyToken = tokens[tokens.length - 1] === '' ? '+' : tokens[tokens.length - 1];
  const parsed = {
    key: keyToken.toLowerCase(),
    mod: false,
    ctrl: false,
    meta: false,
    alt: false,
    shift: false,
  };
  for (const token of tokens.slice(0, -1)) {
    const modifier = token.toLowerCase();
    if (modifier === '') continue; // artifact of a literal '+' key
    if (!MODIFIERS.has(modifier))
      throw new Error(`[ui-core] unknown modifier "${token}" in "${shortcut}"`);
    if (modifier === 'mod') parsed.mod = true;
    else if (modifier === 'ctrl' || modifier === 'control') parsed.ctrl = true;
    else if (modifier === 'meta' || modifier === 'cmd' || modifier === 'command')
      parsed.meta = true;
    else if (modifier === 'alt' || modifier === 'option') parsed.alt = true;
    else parsed.shift = true;
  }
  if (parsed.key === '') throw new Error(`[ui-core] empty key in shortcut "${shortcut}"`);
  return parsed;
}

export function matchShortcut(
  parsed: ParsedShortcut,
  stroke: KeyStroke,
  options: { isMac: boolean },
): boolean {
  const wantCtrl = parsed.ctrl || (parsed.mod && !options.isMac);
  const wantMeta = parsed.meta || (parsed.mod && options.isMac);
  if (stroke.ctrlKey !== wantCtrl) return false;
  if (stroke.metaKey !== wantMeta) return false;
  if (stroke.altKey !== parsed.alt) return false;
  // Shift changes what `key` is for printable characters ('=' vs '+'), so only
  // enforce declared shift; an undeclared shift is rejected for non-printables,
  // and for letters, where it only changes the case: 'Mod+Z' isn't
  // 'Shift+Mod+Z'.
  if (parsed.shift && !stroke.shiftKey) return false;
  const hasCase = parsed.key !== parsed.key.toUpperCase();
  if (!parsed.shift && stroke.shiftKey && (parsed.key.length > 1 || hasCase)) return false;

  const key = stroke.key.toLowerCase();
  if (key === parsed.key) return true;
  // Long names ('numpadadd', 'f1', …) may be codes rather than keys.
  return (
    parsed.key.length > 1 && stroke.code !== undefined && stroke.code.toLowerCase() === parsed.key
  );
}

/**
 * Whether two shortcuts are pressed with the same keys on this platform: `'Mod+S'` and
 * `'Ctrl+s'` are where `Mod` is Ctrl, and not on a Mac.
 */
export function sameShortcut(left: string, right: string, options: { isMac: boolean }): boolean {
  const keysOf = (shortcut: string) => {
    const parsed = parseShortcut(shortcut);
    return [
      parsed.key,
      parsed.ctrl || (parsed.mod && !options.isMac),
      parsed.meta || (parsed.mod && options.isMac),
      parsed.alt,
      parsed.shift,
    ].join(' ');
  };
  return keysOf(left) === keysOf(right);
}

/**
 * How a key shows, by its lowercase name, where that isn't the name itself:
 * on a Mac, then elsewhere. Matches what each platform's own menus show.
 */
const KEY_NAMES: Readonly<Record<string, readonly [mac: string, other: string]>> = {
  arrowleft: ['←', '←'],
  arrowright: ['→', '→'],
  arrowup: ['↑', '↑'],
  arrowdown: ['↓', '↓'],
  backspace: ['⌫', 'Backspace'],
  delete: ['⌦', 'Delete'],
  enter: ['↩', 'Enter'],
  escape: ['Esc', 'Esc'],
  tab: ['⇥', 'Tab'],
  ' ': ['Space', 'Space'],
  space: ['Space', 'Space'],
  pageup: ['Page Up', 'Page Up'],
  pagedown: ['Page Down', 'Page Down'],
  numpadadd: ['Num +', 'Num +'],
  numpadsubtract: ['Num -', 'Num -'],
};

/** A shortcut as a menu or a tooltip shows it: `'⌘K'` on a Mac, `'Ctrl+K'` elsewhere. */
export function formatShortcut(shortcut: string, options: { isMac: boolean }): string {
  const parsed = parseShortcut(shortcut);
  const named = KEY_NAMES[parsed.key];
  const key = named
    ? named[options.isMac ? 0 : 1]
    : parsed.key.length === 1
      ? parsed.key.toUpperCase()
      : capitalize(parsed.key);
  if (options.isMac) {
    const mods = [
      parsed.ctrl ? '⌃' : '',
      parsed.alt ? '⌥' : '',
      parsed.shift ? '⇧' : '',
      parsed.meta || parsed.mod ? '⌘' : '',
    ].join('');
    return `${mods}${key}`;
  }
  const mods = [
    parsed.ctrl || parsed.mod ? 'Ctrl' : '',
    parsed.meta ? 'Meta' : '',
    parsed.alt ? 'Alt' : '',
    parsed.shift ? 'Shift' : '',
  ].filter(Boolean);
  return [...mods, key].join('+');
}

function capitalize(text: string): string {
  return text.charAt(0).toUpperCase() + text.slice(1);
}

/**
 * The i18n controller: reads over the state, the language verbs, the
 * `onLocaleChanged` derivation, and the loader wired at `connect`. Built
 * synchronously in `createKernel()`, so `t()` works before the engine exists.
 */
import {
  isPluginError,
  memo,
  PluginError,
  toPluginError,
  toPluginErrorInfo,
  type OperationOptions,
  type PluginContext,
  type Unsubscribe,
} from '@embedpdf/core';

import type {
  I18nCapability,
  I18nSettings,
  LocaleChangedEvent,
  LocaleInfo,
  LocaleLoadFailedEvent,
  TranslateOptions,
} from './contract';
import {
  addTranslations,
  endLocaleLoad,
  registerLocale,
  seedFromSettings,
  setLocale as setCurrentLocale,
  startLocaleLoad,
  unregisterLocale,
  type I18nState,
} from './model';
import { createLoaders } from './sync/loaders';
import { translate, type TranslationSources } from './translate';

const unknownLocale = (code: string) =>
  new PluginError('not-found', 'i18n', `unknown locale '${code}': not loaded and not in loaders`);

export function createI18nController(ctx: PluginContext<I18nState, I18nSettings>) {
  const settings = ctx.settings();
  const localeChanged = ctx.events.source<LocaleChangedEvent>();
  const localeLoadFailed = ctx.events.source<LocaleLoadFailedEvent>();

  const state = () => ctx.state.get();
  ctx.state.update(seedFromSettings, settings.get());

  // A language change is announced once it shows: never while a language is
  // still loading, and always against the language announced last.
  let announced = state().locale;
  ctx.state.onChange(({ next }) => {
    if (next.loading !== null || next.locale === announced) return;
    const previousLocale = announced;
    announced = next.locale;
    localeChanged.emit({ locale: next.locale, previousLocale });
  });

  const sources = (): TranslationSources => ({
    locale: state().locale,
    fallbackLocale: settings.get().fallbackLocale,
    locales: state().locales,
  });

  // A missing key would otherwise go unnoticed, since `t()` always returns
  // something to show: warn once per key.
  const warned = new Set<string>();
  const translateKey = (key: string, options?: TranslateOptions): string => {
    const result = translate(sources(), key, options);
    const missing =
      options?.fallbackKey === undefined ? `"${key}"` : `"${key}" or "${options.fallbackKey}"`;
    if (!result.found && options?.fallback === undefined && !warned.has(missing)) {
      warned.add(missing);
      console.warn(`[i18n] missing translation ${missing} (locale: ${state().locale})`);
    }
    return result.text;
  };

  /** A new translate function only when the strings it can return may differ. */
  const getTranslator = memo(
    () => [state().locale, state().locales, settings.get().fallbackLocale],
    (_locale, _locales, _fallbackLocale) => (key: string, options?: TranslateOptions) =>
      translateKey(key, options),
  );

  /** The languages a picker shows, rebuilt only when the languages or the loaders change. */
  const listLocales = memo(
    () => [state().locales, settings.get().loaders],
    (locales, loaders): readonly LocaleInfo[] => {
      const known: LocaleInfo[] = Object.values(locales).map((locale) => ({
        code: locale.code,
        name: locale.name,
        direction: locale.direction ?? 'ltr',
        loaded: true,
      }));
      for (const code of Object.keys(loaders)) {
        if (!locales[code]) known.push({ code, name: code, direction: 'ltr', loaded: false });
      }
      return known;
    },
  );

  /** The caller waiting for a language to load; a newer switch replaces it. */
  const pending = new Map<string, { resolve(): void; reject(error: unknown): void }>();
  const settle = (code: string, outcome: { ok: true } | { ok: false; error: unknown }) => {
    const waiter = pending.get(code);
    if (!waiter) return;
    pending.delete(code);
    if (outcome.ok) waiter.resolve();
    else waiter.reject(outcome.error);
  };
  const supersede = () => {
    for (const [code, waiter] of pending) {
      pending.delete(code);
      waiter.reject(
        new PluginError('operation-cancelled', 'i18n', `switching to '${code}' was replaced`),
      );
    }
  };
  const loaders = createLoaders(ctx, settings, { settle }, (locale, error) =>
    localeLoadFailed.emit({ locale, error: toPluginErrorInfo(toPluginError('i18n', error)) }),
  );

  const setLocale = (code: string, options: OperationOptions = {}): Promise<void> => {
    const { signal } = options;
    if (signal?.aborted) {
      return Promise.reject(new PluginError('operation-cancelled', 'i18n', 'operation cancelled'));
    }
    if (state().locales[code]) {
      supersede();
      ctx.state.update(setCurrentLocale, code);
      return Promise.resolve();
    }
    if (!settings.get().loaders[code]) return Promise.reject(unknownLocale(code));
    supersede();
    const loaded = new Promise<void>((resolve, reject) => {
      pending.set(code, { resolve, reject });
      ctx.state.update(startLocaleLoad, code);
    });
    // A cancelled switch stops waiting: the language still registers when it
    // arrives, but doesn't become current.
    signal?.addEventListener(
      'abort',
      () => {
        if (!pending.delete(code)) return;
        ctx.state.update(endLocaleLoad, code);
      },
      { once: true },
    );
    return ctx.cancellable(signal, loaded);
  };

  /** Follow a settings change: new languages register, and a new `locale` becomes current. */
  const followSettings = (): void => {
    let previous = settings.get();
    ctx.listen(settings.api.onSettingsChanged, ({ settings: next, changed }) => {
      if (changed.includes('locales')) {
        for (const locale of previous.locales) {
          if (!next.locales.some((other) => other.code === locale.code)) {
            ctx.state.update(unregisterLocale, locale.code);
          }
        }
        for (const locale of next.locales) {
          if (!previous.locales.includes(locale)) ctx.state.update(registerLocale, locale);
        }
      }
      if (changed.includes('locale')) {
        const code = next.locale ?? next.fallbackLocale;
        // A failed load fires onLocaleLoadFailed; only a code nothing knows needs saying here.
        setLocale(code).catch((error: unknown) => {
          if (isPluginError(error, 'not-found')) console.warn(`[i18n] ${error.message}`);
        });
      }
      previous = next;
    });
  };

  const api: I18nCapability = {
    ...settings.api,
    t: translateKey,
    getTranslator,
    hasKey: (key) => translate(sources(), key).found,
    getLocale: () => state().locale,
    getDirection: () => state().locales[state().locale]?.direction ?? 'ltr',
    listLocales,
    getLoadingLocale: () => state().loading,
    setLocale,
    registerLocale: (locale): Unsubscribe => {
      ctx.state.update(registerLocale, locale);
      return () => ctx.state.update(unregisterLocale, locale.code);
    },
    addTranslations: (code, translations) => {
      // A language in `loaders` takes strings before it has loaded; they merge in when it does.
      if (!state().locales[code] && !settings.get().loaders[code]) throw unknownLocale(code);
      ctx.state.update(addTranslations, code, translations);
    },
    onLocaleChanged: localeChanged.on,
    onLocaleLoadFailed: localeLoadFailed.on,
  };

  return {
    api,
    connect() {
      loaders.connect();
      followSettings();
    },
  };
}

/**
 * The lookup: a key in, a string out. Pure, with no platform access
 * (`Intl.PluralRules` is core ECMAScript, not DOM).
 */
import type { Locale, TranslateOptions, TranslationDictionary } from './contract';
import { embedpdfStringsFor } from './strings';

/** Walk a dotted path (`'commands.zoom.in'`) through a dictionary. */
function lookup(
  dictionary: TranslationDictionary | undefined,
  key: string,
): string | TranslationDictionary | undefined {
  if (!dictionary) return undefined;
  let node: string | TranslationDictionary | undefined = dictionary;
  for (const part of key.split('.')) {
    if (node === undefined || typeof node === 'string') return undefined;
    node = node[part];
  }
  return node;
}

/** The language's plural form for a count; `'one'` or `'other'` when the runtime has no rules for it. */
function pluralCategory(locale: string, count: number): string {
  try {
    return new Intl.PluralRules(locale).select(count);
  } catch {
    return count === 1 ? 'one' : 'other';
  }
}

/** A string is the answer; a branch needs a plural form, picked by `params.count`. */
function resolveNode(
  node: string | TranslationDictionary | undefined,
  locale: string,
  params?: Record<string, string | number>,
): string | undefined {
  if (typeof node === 'string') return node;
  if (node !== undefined && typeof params?.count === 'number') {
    const branch = node[pluralCategory(locale, params.count)] ?? node['other'];
    if (typeof branch === 'string') return branch;
  }
  return undefined;
}

/** Fill in `{name}` slots; a slot without a value stays as it is, so it shows while testing. */
export function interpolate(text: string, params?: Record<string, string | number>): string {
  if (!params) return text;
  return text.replace(/\{(\w+)\}/g, (match, slot) =>
    params[slot] !== undefined ? String(params[slot]) : match,
  );
}

/** What a lookup reads: the two languages it tries, and the app's strings. */
export interface TranslationSources {
  readonly locale: string;
  readonly fallbackLocale: string;
  /** The app's loaded languages, by code. */
  readonly locales: Readonly<Record<string, Locale>>;
}

export interface TranslateResult {
  readonly text: string;
  /** False when no language has the key: `text` is then the fallback or the key. */
  readonly found: boolean;
}

/** A key in one language: the app's string, then EmbedPDF's own. */
const stringIn = (
  sources: TranslationSources,
  code: string,
  key: string,
  params?: Record<string, string | number>,
): string | undefined =>
  resolveNode(lookup(sources.locales[code]?.translations, key), code, params) ??
  resolveNode(lookup(embedpdfStringsFor(code), key), code, params);

/**
 * A key's string: in the current language (the key, then `options.fallbackKey`), then the same in
 * the fallback language, then `options.fallback` (with its slots filled too), then the key itself.
 */
export function translate(
  sources: TranslationSources,
  key: string,
  options?: TranslateOptions,
): TranslateResult {
  const params = options?.params;
  const fallbackKey = options?.fallbackKey;
  const inLanguage = (code: string) =>
    stringIn(sources, code, key, params) ??
    (fallbackKey === undefined ? undefined : stringIn(sources, code, fallbackKey, params));
  const text = inLanguage(sources.locale) ?? inLanguage(sources.fallbackLocale);
  if (text !== undefined) return { text: interpolate(text, options?.params), found: true };
  if (options?.fallback !== undefined)
    return { text: interpolate(options.fallback, options.params), found: false };
  return { text: key, found: false };
}

/**
 * The shell controller: reads, verbs that apply the pure transitions in
 * `model.ts`, and the surface and menu events. The events are derived in one
 * place, from each state change, so a new verb can never forget to announce.
 */
import { memo, memoByKey, type PluginContext } from '@embedpdf/core';

import type {
  MenuClosedEvent,
  MenuOpenedEvent,
  ShellCapability,
  SurfaceClosedEvent,
  SurfaceOpenedEvent,
  SurfaceState,
} from './contract';
import {
  applySnapshot,
  closeAllMenus,
  closeAllSurfaces,
  closeMenu,
  closeSurface,
  openMenu,
  openSurface,
  setSurfaceProps,
  snapshotOf,
  toggleMenu,
  toggleSurface,
  type ShellState,
} from './model';

export function createShellController(ctx: PluginContext<ShellState>) {
  const surfaceOpened = ctx.events.source<SurfaceOpenedEvent>();
  const surfaceClosed = ctx.events.source<SurfaceClosedEvent>();
  const menuOpened = ctx.events.source<MenuOpenedEvent>();
  const menuClosed = ctx.events.source<MenuClosedEvent>();

  ctx.state.onChange(({ previous, next }) => {
    if (previous.surfaces !== next.surfaces) {
      const ids = new Set([...Object.keys(previous.surfaces), ...Object.keys(next.surfaces)]);
      for (const id of ids) {
        const wasOpen = previous.surfaces[id]?.open ?? false;
        const isOpen = next.surfaces[id]?.open ?? false;
        if (wasOpen === isOpen) continue;
        if (isOpen) surfaceOpened.emit({ id, props: next.surfaces[id].props });
        else surfaceClosed.emit({ id });
      }
    }
    if (previous.openMenus !== next.openMenus) {
      for (const id of previous.openMenus) {
        if (!next.openMenus.includes(id)) menuClosed.emit({ id });
      }
      for (const id of next.openMenus) {
        if (!previous.openMenus.includes(id)) menuOpened.emit({ id });
      }
    }
  });

  const state = () => ctx.state.get();

  /** A surface's public shape, the same object until its record changes. */
  const surfaceOf = memoByKey(
    (id: string) => [state().surfaces[id]],
    (id, surface): SurfaceState | null => (surface ? { id, ...surface } : null),
  );
  const listOpenSurfaces = memo(
    () => [state().surfaces],
    (surfaces) =>
      Object.keys(surfaces)
        .filter((id) => surfaces[id].open)
        .map((id) => surfaceOf(id)!),
  );

  const api: ShellCapability = {
    isOpen: (id) => state().surfaces[id]?.open ?? false,
    getSurface: surfaceOf,
    listOpenSurfaces,
    open: (id, options) => ctx.state.update(openSurface, id, options),
    close: (id) => ctx.state.update(closeSurface, id),
    toggle: (id, options) => ctx.state.update(toggleSurface, id, options),
    updateSurfaceProps: (id, props) => ctx.state.update(setSurfaceProps, id, props),
    closeAll: () => ctx.state.update(closeAllSurfaces),
    isMenuOpen: (id) => state().openMenus.includes(id),
    listOpenMenus: () => state().openMenus,
    openMenu: (id) => ctx.state.update(openMenu, id),
    closeMenu: (id) => ctx.state.update(closeMenu, id),
    toggleMenu: (id) => ctx.state.update(toggleMenu, id),
    closeAllMenus: () => ctx.state.update(closeAllMenus),
    getSnapshot: memo(() => [state()], snapshotOf),
    applySnapshot: (snapshot) => ctx.state.update(applySnapshot, snapshot),
    onSurfaceOpened: surfaceOpened.on,
    onSurfaceClosed: surfaceClosed.on,
    onMenuOpened: menuOpened.on,
    onMenuClosed: menuClosed.on,
  };
  return { api };
}

import type { PdfPageActions } from './PdfAction';
import type { PdfRect, PdfRotation, PdfSize } from '../geometry/primitives';
import type { PageRef } from '../identity/PageRef';
import type { Coordinates, PageCoordinates } from '../pageSpace/coordinates';

/**
 * The five PDF page boundary boxes as ISO 32000-1 §14.11.2 defines them: the
 * crop box defaults to the media box and the other three to the crop box, and
 * each is reduced to the part it shares with the media box. `crop` is the
 * visible page, what the page shows, so in page space it is
 * `{ x: 0, y: 0, width, height }` and the others are measured from its
 * top-left corner.
 *
 * The page's turn (`rotation`) never changes these numbers.
 */
export interface PageBoxes<C extends Coordinates = PageCoordinates> {
  media: C['box'];
  crop: C['box'];
  bleed: C['box'];
  trim: C['box'];
  art: C['box'];
}

/**
 * The order a page's annotations take keyboard focus in (`/Tabs`): row by
 * row, column by column, in the structure tree's order, in the order the
 * page lists them (`annotations`, PDF 2.0), or its form fields first in
 * that order (`widgets`, PDF 2.0).
 */
export type PageTabOrder = 'rows' | 'columns' | 'structure' | 'annotations' | 'widgets';

/**
 * Static attributes for one page. This is the per-page element returned by
 * `pages.list()`.
 *
 * `size` is the un-rotated size of the visible page (`boxes.crop`), not
 * swapped for rotation.
 * `rotation` is a separate field; the SDK swaps width/height for 90/270 to
 * derive the on-screen display size. Keeping the wire un-rotated keeps it
 * consistent with the raw `boxes` and with the "transform lives in the SDK"
 * principle.
 */
export interface PageLayout<C extends Coordinates = PageCoordinates> {
  /** Display order at read time. Not an identity; shifts on a page move. */
  index: number;
  /**
   * The page's durable identity. The only safe key for cross-call
   * correlation and what every leaf URL (`/pages/{pageKey}/...`) is
   * addressed by; `index` is display order.
   */
  ref: PageRef;
  /** `/PageLabels` entry, or `null` when the PDF declares no label (the SDK
   * falls back to `index + 1`). */
  label: string | null;
  /** Un-rotated crop dimensions in PDF points. */
  size: PdfSize;
  rotation: PdfRotation;
  /** `/UserUnit`; defaults to the PDF default of 1. */
  userUnit: number;
  /** The order its annotations take keyboard focus in; `null` when the page doesn't say. */
  tabOrder: PageTabOrder | null;
  boxes: PageBoxes<C>;
  /**
   * Where the page sits in the file: its visible box (`boxes.crop`) in PDF
   * space, the numbers PDF tools use. The only PDF-space value in the API;
   * convert a page-space value with it (`pdfRectOf(rect, layout.pdfCropBox)`).
   */
  pdfCropBox: PdfRect;
  /** Page-owned `/AA` actions; absent for the usual script-less page. */
  actions?: PdfPageActions<C['destination']>;
}

import type { PageObjectNumber } from './PageObjectNumber';
import { isValidPageObjectNumber } from './PageObjectNumber';

/**
 * How callers address a page — the page-plane sibling of `AnnotationRef`
 * and `FormFieldRef`.
 *
 * `objectNumber` is the indirect object number of the page dictionary.
 * ISO 32000-1 §7.7.3.3 requires every `/Kids` entry to be an indirect
 * reference, the layer runtime never renumbers (frozen base + incremental
 * deltas), and a deleted page's number is retired, never recycled — so it
 * is the durable identity for the lifetime of a document. It is what every
 * `PageLayout.ref` and `PageHandle.ref` carries.
 *
 * It is deliberately the only kind. Pages are durable by construction (see
 * `PagesMutator`): a display index is never an identity, a page without an
 * object number is refused at open (`MalformedPdf`), and a `/Names /Pages`
 * key is a registry entry the layout already maps to a number, not a second
 * identity the engine would ever return. The discriminated shape keeps the
 * address consistent with the other refs and leaves room for an additive
 * kind should a real one ever appear.
 *
 * Records that mention a page (an annotation ref, event payloads, per-page
 * results, destinations, search matches) carry the same `page: PageRef`;
 * `toPageRef()` builds one from a page number you already hold.
 */
export type PageRef = { kind: 'objectNumber'; objectNumber: PageObjectNumber };

/** Build the address for a page from its object number. */
export function toPageRef(pageObjectNumber: PageObjectNumber): PageRef {
  return { kind: 'objectNumber', objectNumber: pageObjectNumber };
}

/** Structural equality for two page addresses. */
export function pageRefsEqual(a: PageRef, b: PageRef): boolean {
  return a.kind === b.kind && a.objectNumber === b.objectNumber;
}

/**
 * URL-safe encoding of a `PageRef`, used by the cloud HTTP surface as the
 * `:pageKey` route parameter. Mirrors `encodeAnnotKey` (`obj:42` /
 * `base:2`) and `encodeFieldRefKey` (`obj:12` / `fqn:…`), so every identity
 * reads the same on the wire:
 *
 *   `{ kind: 'objectNumber', objectNumber: 3 }` -> `'obj:3'`
 *
 * The caller is responsible for `encodeURIComponent`-ing the result before
 * splicing it into a URL path; the `wirePaths` builders already do that.
 */
export function encodePageKey(ref: PageRef): string {
  if (!isValidPageObjectNumber(ref.objectNumber)) {
    throw new RangeError(
      `encodePageKey: objectNumber must be a positive integer, got ${ref.objectNumber}`,
    );
  }
  return `obj:${ref.objectNumber}`;
}

/**
 * Inverse of `encodePageKey`. Returns `null` for malformed input so the
 * server can answer 400 InvalidArg with a useful message instead of
 * throwing. The input is the already-`decodeURIComponent`-ed segment from
 * the route path.
 */
export function decodePageKey(key: string): PageRef | null {
  if (!key.startsWith('obj:')) return null;
  const rest = key.slice('obj:'.length);
  const n = Number.parseInt(rest, 10);
  if (!Number.isInteger(n) || n <= 0 || String(n) !== rest) return null;
  return { kind: 'objectNumber', objectNumber: n };
}

