/** The commands slice: only the serializable category gates. Definitions
 *  hold functions and live in the controller's registry. */
export interface CommandsState {
  readonly disabledCategories: readonly string[];
}

export type CommandsAction =
  | { type: 'COMMANDS/DISABLE_CATEGORY'; category: string }
  | { type: 'COMMANDS/ENABLE_CATEGORY'; category: string }
  | { type: 'COMMANDS/SET_DISABLED_CATEGORIES'; categories: readonly string[] };

export const initialCommandsState = (disabled: readonly string[] = []): CommandsState => ({
  disabledCategories: [...disabled],
});

export function commandsReducer(state: CommandsState, action: CommandsAction): CommandsState {
  switch (action.type) {
    case 'COMMANDS/DISABLE_CATEGORY':
      return state.disabledCategories.includes(action.category)
        ? state
        : { disabledCategories: [...state.disabledCategories, action.category] };
    case 'COMMANDS/ENABLE_CATEGORY':
      return state.disabledCategories.includes(action.category)
        ? { disabledCategories: state.disabledCategories.filter((c) => c !== action.category) }
        : state;
    case 'COMMANDS/SET_DISABLED_CATEGORIES':
      return { disabledCategories: [...action.categories] };
    default:
      return state;
  }
}

/** The definition registry: definitions plus their pre-parsed shortcuts. */
import { PluginError } from '@embedpdf/core';
import { parseShortcut, type ParsedShortcut } from '@embedpdf/core-ui';

import type { CommandDef, RegisterCommandOptions } from './contract';

export interface RegisteredCommand {
  readonly def: CommandDef;
  readonly shortcuts: readonly string[];
  readonly parsed: readonly ParsedShortcut[];
}

export type CommandRegistry = Map<string, RegisteredCommand>;

export function registerCommand(
  registry: CommandRegistry,
  def: CommandDef,
  options: RegisterCommandOptions = {},
): RegisteredCommand {
  if (registry.has(def.id) && !options.replace) {
    throw new PluginError('conflict', 'commands', `duplicate command '${def.id}'`);
  }
  const shortcuts = def.shortcut === undefined ? [] : ([] as string[]).concat(def.shortcut);
  const entry: RegisteredCommand = { def, shortcuts, parsed: shortcuts.map(parseShortcut) };
  registry.set(def.id, entry);
  return entry;
}

/**
 * The commands state: only the serializable category gates. Definitions hold
 * functions, so they live in the controller's registry. Every function below
 * is a pure transition; the controller applies them with `ctx.state.update`.
 */
export interface CommandsState {
  readonly disabledCategories: readonly string[];
}

export const initialCommandsState = (disabled: readonly string[] = []): CommandsState => ({
  disabledCategories: [...disabled],
});

export function disableCategory(state: CommandsState, category: string): CommandsState {
  if (state.disabledCategories.includes(category)) return state;
  return { disabledCategories: [...state.disabledCategories, category] };
}

export function enableCategory(state: CommandsState, category: string): CommandsState {
  if (!state.disabledCategories.includes(category)) return state;
  return { disabledCategories: state.disabledCategories.filter((other) => other !== category) };
}

export function setDisabledCategories(
  state: CommandsState,
  categories: readonly string[],
): CommandsState {
  const unchanged =
    categories.length === state.disabledCategories.length &&
    categories.every((category, index) => category === state.disabledCategories[index]);
  return unchanged ? state : { disabledCategories: [...categories] };
}

